window.LECTURE_DRILL = {
  "mzt_s1": [{n:"(1)",q:"【2010.21】中国革命、建设和改革的实践证明，要运用马克思主义指导实践，必须实现马克思主义中国化，马克思主义之所以能够中国化的原因在于 (A) 马克思主义理论的内在要求 (B) 马克思主义与中华民族优秀文化具有相融性 (C) 中国革命、建设和改革的实践需要马克思主义指导 (D) 马克思主义为中国革命、建设和改革提供了现实的发展模式",a:"(ABC)",sol:""},{n:"(2)",q:"【2011.21】在马克思主义中国化的过程中，产生了毛泽东思想和中国特色社会主义理论体系，这两大理论成果的一脉相承性主要体现在，二者具有共同的（ (A) 马克思主义的理论基础 (B) 革命和建设的根本任务 (C) 实事求是的理论精髓 (D) 和平与发展的时代背景微信公众号：djky6微信公众号：djky66（顶尖考研祝您上岸）（顶尖考研祝您上岸）0032024考研政治知识精讲讲义（毛特分册）",a:"(AC)",sol:""}],
  "mzt_s2": [{n:"(1)",q:"【2016.5】毛泽东思想和中国特色社会主义理论体系是马克思主义中国化的两大理3.毛泽东思想不包括改革内容，邓小平思论成果。贯穿这两大理论成果始终，并体现在两大成果各个基本观点中的世界观想不包括革命内容。和方法论的基础是4.毛泽东思想≠毛泽东的思想。 (A) 群众路线 (B) 独立自主公众号：djky66 (C) 实事求是 (D) 改革创新",a:"(C)",sol:""},{n:"(2)",q:"【2012.5】毛泽东曾在不同场合多次谈到，调查研究有两种方法，一种是走马看花，一种是下马看花。走马看花、不深人，还必须用第二种方法，就是下马看花，仔细看花，分析一朵花。毛泽东强调“下马看花”的实际意义在于C (A) 解决实际问题必须要有先进理论的指导 (B) 运用多种综合方法分析调查研究的材料 (C) 马克思主义理论必须适合中国革命的具体实际 (D) 只有全面深入地了解中国的实际，才能找出规律",a:"(D)",sol:""},{n:"(3)",q:"【2021.5】毛泽东思想作为马克思主义中国化的第一个重大理论成果，是由一系列相互联系的重要理论观点所构成的完整的科学思想体系。这一科学思想体系所围绕的主题是 (A) 中国革命和建设 (B) 中国命运和前途 (C) 中国社会性质和阶级状况 (D) 中国改革和发展·008.",a:"(A)",sol:""}],
  "mzt_s3": [{n:"(1)",q:"【2012.10】毛泽东在《中国革命和中国共产党》中论述了民主革命和社会主义革命的关系。他指出：“民主革命是社会主义革命的必要准备，社会主义革命是民主 (A) 资本主义道路在中国走不通 (B) 俄国十月革命为中国提供了经验 (C) 民主革命中包含了社会主义因素 (D) 中国国情决定中国革命必须分两步走",a:"(C)",sol:""},{n:"(2)",q:"【2014.12】中共七大政治报告指出：“房子是应该经常打扫的，不打扫就会积满灰尘；脸是应该经常洗的，不洗也就会灰尘满面。我们同志的思想、我们党的工作，也会沾染灰尘的，也应该打扫和洗涤。”这段话形象地反映了中国共产党在长期革命实践中所形成的C (A) 艰苦奋斗的优良作风 (B) 理论联系实际的优良作风 (C) 密切联系群众的优良作风 (D) 批评与自我批评的优良作风·018.",a:"(D)",sol:""}],
  "mzt_s4": [{n:"(1)",q:"【2012.21】从中华人民共和国成立到社会主义改造基本完成，是我国从新民主主义到社会主义的过渡时期。这一时期中国社会的阶级构成主要包括 (A) 工人阶级 (B) 农民阶级 (C) 民族资产阶级 (D) 城市小资产阶级",a:"(ABCD)",sol:""},{n:"(2)",q:"【2017.5】从中华人民共和国成立到社会主义改造基本完成，是我国从新民主义到社会主义的过渡时期。这一时期，个体经济向社会主义集体经济过渡的形式是 (A) 国营经济 (B) 私人资本主义经济 (C) 合作社经济 (D) 国家资本主义经济",a:"(C)",sol:""},{n:"(3)",q:"【2010.22】1952年，党中央在配酿过渡时期总路线时，毛泽东把实现向社会主义转变的设想，由建国之初的“先搞工业化建设，再一举过渡”改变为“建设和改造同时并举，逐步过渡”。这一改变原因和条件是HL66 (A) 我国社会主义经济因素的不断增长和对资本主义经济的限制 (B) 为了确定我国工业化建设的社会主义方向 (C) 我国工业化建设取得了重大成就祝您上岸） (D) 民主革命的遗留任务已经完成·024",a:"(ABD)",sol:""}],
  "mzt_s5": [{n:"(1)",q:"【2015.5】新中国的工业化是在苏联的影响下起步的。走中国工业化道路，是中国共产党初步探索我国社会主义建设道路的一个重要思想。当时所讲的工业化道路问题，主要是指 (A) 中央和地方的关系问题 (B) 经济建设和国防建设的关系问题 (C) 沿海工业和内地工业的关系问题 (D) 重工业、轻工业和农业的发展关系问题",a:"(D)",sol:""},{n:"(2)",q:"【2016.6】社会主义基本制度确立后，如何在中国这样一个经济文化比较落后的东方大国建设和巩固社会主义，是党面临的全新课题。1956年4月，毛泽东作了《论十大关系》的报告，在初步总结我国社会主义建设经验的基础上，从十个方面论述了我国社会主义建设需要重点把握的重大关系。“十大关系”所围绕的基本方针是瓜伙专 (A) 集中力量向科学进军您上岸） (B) 调动一切积极因素为社会主义事业服务 (C) 既反保守又反冒进、在综合平衡中稳步前进 (D) 正确处理人民内部矛盾",a:"(B)",sol:""},{n:"(3)",q:"【2021.22】社会主义基本制度确立以后，如何在中国这样一个经济文化比较落后的东方大国建设和巩固社会主义，是党面临的一项崭新课题。为找到一条适合中国国情的社会主义建设道路，党带领人民进行了艰难曲折的初步探索。这一初步探索的意义主要体现在 (A) 实现了马克思主义中国化的第二次飞跃 (B) 丰富了科学社会主义的理论和实践 (C) 巩固和发展了我国的社会主义制度 (D) 为开创中国特色社会主义提供了宝贵经验、理论准备和物质基础029",a:"(BCD)",sol:""}],
  "mzt_s6": [{n:"(1)",q:"【2013.25】1992年年初，邓小平在南方谈话中指出：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。”这一概括对社会主义传统认识的突破主要体现在 (A) 破除了脱离生产力水平抽象谈论社会主义的认识 (B) 否定了社会主义必须坚持公有制和按劳分配原则的认识 (C) 纠正了把社会主义本质等同于社会主义具体做法的认识 (D) 摆脱了长期以来忽视建设社会主义根本目的和目标的认识持不忘初心、继续前进，要坚持党的基本路线不动摇，不断把中国特色社会主义伟大事业推向前进。”改革开放以来，党和国家领导人一再强调要毫不动摇地坚持微信公众号：djky66党的基本路线，这主要是因为，实践已经证明党的基本路线是djky66",a:"(ACD)",sol:""},{n:"(3)",q:"【2020.5】“什么是社会主义、怎样建设社会主义”是邓小平在领导改革开放和现代化建设这一新的革命过程中，不断提出和反复思考的首要的基本理论问题。搞清楚这一问题的关键是 (A) 在认清基本国情的基础上，进一步把握我国社会主义的发展阶段 (B) 在正确分析我国社会主要矛盾的基础上，进一步明确社会主义的根本任务 (C) 在坚持社会主义基本制度的基础上，进一步认清社会主义的本质 (D) 在总结我国社会主义历史经验的基础上，进一步揭示社会主义社会发展的一般规律·035·2024考研政治知识精讲讲义（毛特分册）",a:"(C)",sol:"【简析】“什么是社会主义、怎样建设社会主义”，是邓小平在领导改革开放和现代化建设这一新的革命过程中，不断提出和反复思考的首要的基本的理论问题。A正确。"}],
  "mzt_s9": [{n:"(1)",q:"【2019.22】中国特色社会主义进人新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。但是，我国社会主义矛盾的变化没有改变我们对我国社会主义所处历史阶段的判断，依据是（） (A) 我国仍然是世界上最大的发展中国家 (B) 我国仍然面临极其复杂的国际环境 (C) 我国总体上仍处于不发达阶段 (D) 我国社会主要矛盾的变化只是社会主义初级阶段这个历史阶段中的变化",a:"(ACD)",sol:"【简析】新时代我国社会主要矛盾的变化是关系全局的历史性变化，但它是在社会主义初级阶段中发生的变化：没有改变对我国社会主义所处历史阶段的判断，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变。A、B、C正确。我国社会主要矛盾的变化是我们党作出中国特色社会主义进入新时代重大判断的基本依据。2012年党的十八大开启了中国特色社会主义新时代，我国全面建成小康社会是在2021年，认为我国社会主要矛盾的变化“正确反映了我国全面建成小康社会之后的新特点”的说法无疑是错误的。D不选。"},{n:"(2)",q:"【2020.22】中国特色社会主义进人新时代，人民群众的新期特内容更广泛，不仅关注“有没有”，更关注“好不好”；不仅包括既有的物质文化需求，更包括在此基础上衍生出来的获得感、幸福感、安全感及尊严、权利等新需求。这一变化表明 (A) 我国社会主要矛盾发生了历史性变化 (B) 我国已经满足了人民“从有到优”的需求 (C) 人民群众对日益增长的物质文化需要出现了阶段性新特征 (D) 我国不平衡不充分的发展已成为制约满足人民需要的主要根源",a:"(ACD)",sol:""}],
  "mzt_s11": [{n:"(1)",q:"【2021.7】改革开放以来，我们党总结正反两方面经验，确立了公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度。在这一基本经济制度中，坚持公有制的主体地位，是因为 (A) 公有制经济是社会主义市场经济的重要组成部分 (B) 公有制是我国经济社会发展的重要基础 (C) 生产资料所有制决定社会的基本性质和发展方向 (D) 由生产资料所有制决定的分配方式能使一切社会成员实现全面发展",a:"(C)",sol:""},{n:"(2)",q:"【2022.5】共同富裕是社会主义的本质要求，是中国式现代化的重要特征。党的十九届五中全会对扎实推动共同富裕作出重大战略部署，明确提出了推进共同富裕的2035年远景目标。这一目标是 (A) 全体人民共同富裕基本实现 (B) 全体人民共同富裕取得更为明显的实质性进展 (C) 全体人民共同富裕全面实现 (D) 全体人民共同富裕同步实现",a:"(B)",sol:""},{n:"(3)",q:"【2020.71人民政协作为统一战线的组织、多党合作和政治协商的机构、人民民主的重要实现形式，是具有中国特色的制度安排。2019年9月20日，习近平在中央政协工作会议暨庆祝中国人民政治协商会议成立70周年大会上的讲话中，提出了新时代加强和改进人民政协工作的总体要求，指出新时代做好人民政协工作的中心环节是 (A) 提高政治协商、民主监督、参政议政水平 (B) 加强思想政治引领，广泛凝聚共识 (C) 发挥好人民政协专门协商机构作用 (D) 强化政协委员责任担当",a:"(B)",sol:""},{n:"(4)",q:"【2022.24】中国共产党自成立以来不断探索和发展适合中国国情的民主道路，使人民民主在东方大国落地生根、繁荣发展。党的十八大以来，我们党不断深化对民主政治发展规律的认识，践行以人民为中心的发展思想，积极发展全过程人民民主。全过程人民民主 (A) 是完整制度程序和完整参与实践有机统一的民主 (B) 是全链条、全方位、全覆盖的民主 (C) 是最广泛、最真实、最管用的社会主义民主 (D) 实现了过程民主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志相统一·066·",a:"(ABCD)",sol:""},{n:"(5)",q:"【2022.8】文化软实力集中体现了一个国家基于文化而具有的凝聚力和生命力，以及由此产生的吸引力和影响力。提高国家文化软实力需要强大的国际传播能力。我国加强国际传播能力建设的重要任务是 (A) 加快发展新型文化业态 (B) 推进中华传统文化创造性转化、创新性发展 (C) 推进社会主义先进文化深入人心，激发全民族文化创造活力 (D) 讲好中国故事，传播好中国声音，展现真实、立体、全面的中国",a:"(D)",sol:""},{n:"(6)",q:"【2021.24】“十三五”时期，我国大气污染治理取得明显成效。来自生态环境部的数据显示，与2015年相比，2019年细颗粒物（PM2.5）未达标地级及以上城市年均浓度下降23.1%，全国337个地级及以上城市年均优良天数比例达到82%。2020年1月至8月，这一比例达到86.7%，PM2.5浓度为31微克/立方米，同比下降11.4%，蓝天白云的好天气正在成为常态。我国大气污染治理取得明显成效，主要得益于 (A) 坚持全民共治、源头防治 (B) 把突出环境问题作为生态文明建设的着力点 (C) 构建生态廊道和生物多样性保护网络 (D) 不断完善生态环境保护制度和强化环保督察微信公众号：djky66（顶尖考研祝您上岸）0672024考研政治知识精讲讲义（毛特分册）",a:"(ABD)",sol:""}],
  "mzt_s12": [{n:"(1)",q:"【2020.24】消除贫困，改善民生，逐步实现共同富裕，是社会主义的本质要求，是我们党的重要使命，新中国成立70年来，已有7亿多人摆脱贫困，占全球减贫人口的70%以上，中国是第一个完成联合国千年发展目标中减贫目标的发展中国家，也是唯一个实现了经济较快增长与大规模减贫同步、综合国力增强与人民生活水平提高同步这一历史性跨越的发展中国家。进人新时代，为了确保到2020年现行标准下农村贫困人口实现脱贫、贫困县全部摘帽的目标，我国采取的重要举措是 (A) 坚持精准扶贫、精准脱贫 (B) 强化党政一把手负总责的责任制 (C) 注重扶贫同扶志扶智相结合 (D) 重点攻克深度贫困地区脱贫任务",a:"(ABCD)",sol:""},{n:"(2)",q:"【2011.24】改革、发展、稳定好比现代化建设棋盘上的三招紧密关联的战略性棋子，每一招棋都下好了，相互促进，就会全局皆活；如果有一招下不好，其他两招也会陷入困境，就可能全局受挫。改革开放以来，党在处理改革、发展、稳定关系方面积累的经验和主要原则包括 (A) 保持改革、发展、稳定在动态中的相互协调和相互促进y66 (B) 把实现社会稳定作为促进改革、发展的根本出发点 (C) 把改革的力度、发展的速度和社会可以承受的程度统一起来 (D) 把不断改善人民生活作为处理改革、发展、稳定关系的重要结合点",a:"(ACD)",sol:""},{n:"(3)",q:"【2019.24】国家治理体系是在党领导下管理国家的制度体系，是一整套紧密相连、相互协调的国家制度；国家治理能力则是运用国家制度管理社会各方面事务的能力。二者的关系主要表现为 (A) 提高国家治理能力可以充分发挥国家治理体系的效能 (B) 好的国家治理体系可以提高国家治理能力 (C) 国家治理体系和治理能力是相辅相成的有机整体 (D) 国家治理体系越完备国家治理能力就一定越强",a:"(ABC)",sol:""},{n:"(4)",q:"【2019.7】高度重视和不断加强党的自身建设，是中国共产党从小到大、由弱到强，从挫折中奋起，在战胜困难中不断成熟的一大法宝，也是党领导的伟大事业不断取得胜利的根本保证。中国特色社会主义进入新时代，党的建设的根本方针是 (A) 全面加强党的执政本领 (B) 坚持党要管党、全面从严治党 (C) 坚持解放思想、改革创新 (D) 全面推进党的政治建设075·2024考研政治知识精讲讲义（毛特分册）",a:"(B)",sol:""}],
  "mzt_s13": [{n:"(1)",q:"【2019.6】党的十八大以来，为了更好适应我国国家安全面临的新形势新任务，实现国家长治久安，我们党明确提出了总体国家安全观。总体国家安全观的宗旨是 (A) 政治安全 (B) 经济安全 (C) 人民安全 (D) 军事、文化、社会安全",a:"(C)",sol:""},{n:"(2)",q:"【2018.8】解决台湾问题，实现祖国完全统一，是全体中华儿女共同愿望，是中华民族根本利益所在。党的十八大以来，在以习近平同志为核心的党中央坚强领导下，在两岸同胞共同努力下，两岸关系取得重要积极成果。两岸关系和平发展的政治基础是 (A) 深化两岸利益融合，共创两岸互利双赢，增进两岸同胞福祉 (B) 相互尊重，求同存异 (C) 增强两岸同胞的民族认同、文化认同、国家认同 (D) 坚持“九二共识”，反对“台独”·081.2024考研政治知识精讲讲义（毛特分册）",a:"(D)",sol:""},{n:"(3)",q:"【2020.26】“一国两制”是实现祖国和平统一的一项重要制度，是中国特色社会主义的一个伟大创举。2019年11月，国家主席习近平在巴西利亚出席金砖国家领导人第十一次会唔时，针对香港出现的街头暴力犯罪行为发表重要讲话。习近平指出，香港持续发生的激进暴力犯罪行为，严重践踏法治和社会秩序，严重破坏香港繁荣稳定，严重挑畔“一国两制”原则底线。止暴制乱、恢复秩序是香港当前最紧迫的任务。贯彻落实“一国两制”方针，绝不能允许触碰的原则底线是 (A) 危害国家主权安全 (B) 干扰内地与香港的民间交流 (C) 挑战中央权力与香港特别行政区基本法权威 (D) 利用香港对内地进行渗透破坏微信公众号：djky66（顶尖考研祝您上岸）082",a:"(ACD)",sol:""}],
  "mzt_s14": [{n:"(2)",q:"【2017.23】“一带一路”倡议提出三年来，已经有100多个国家和国际组织参与其中，我国同沿线30多个国家签署共建合作协议，与20多个国家开展了国际产能合作，一批有影响力的标志性项目逐步落地。截至2016年7月，我国对“一带一路”相关国家的投资累计已达511亿美元，占同期对外直接投资总额的12%：与沿线国家新签承包工程合同1.25万份，累计合同额2790亿美元。我国推进“一带一路”建设旨在 (A) 统筹国内国际两个大局 (B) 促进沿线各国共同繁荣 (C) 打造开放、包容、均衡、普惠的区域经济合作架构 (D) 探索国际合作及全球治理新模式.087.2024考研政治知识精讲讲义（毛特分册）",a:"(ABCD)",sol:""}],
  "mayuan_s2": [{n:"(1)",q:"【1998.文3】全部马克思主义学说的核心和理论结论是 (A) 唯物史观 (B) 剩余价值学说 (C) 科学社会主义 (D) 无产阶级专政学说",a:"(C)",sol:""},{n:"(3)",q:"【1991.文61马克思一生中最重要的理论发现是③生物进化论。 (A) 无产阶级革命和无产阶级专政学说 (B) 社会主义和共产主义学说djky微信公众号：djky66 (C) 唯物史观和剩余价值学说（顶尖考研祝您上岸） (D) 关于无产阶级政党和无产阶级领袖的学说主工T之您上岸）",a:"(C)",sol:""},{n:"(4)",q:"【1997.文1】马克思主义的直接理论来源是 (A) 法国唯物主义、英国经验主义、德国理性主义 (B) 细胞学说、能量守恒定律、生物进化论 (C) 德国古典哲学、英国古典政治经济学、英法空想社会主义 (D) 法国历史哲学、英国科学主义、欧洲人文主义",a:"(C)",sol:""},{n:"(5)",q:"【2018.11马克思主义的产生具有深刻的社会根源、阶级基础和思想渊源。其创始人马克思1818年5月5日出生在德国特利尔城的一个律师家庭，恩格斯1820年11月28日出生在德国巴门市的一个工厂主家庭，他们放弃了舒适安逸的生活，毅然选择了充满荆棘坎坷的革命道路，创立了科学社会主义。马克思、恩格斯之所以能够创立科学社会主义，主要是因为 (A) 他们拥有优良的家庭背景和教育经历 (B) 他们对时代有着超越常人的认知能力 (C) 社会历史条件和个人努力的相互作用 (D) 德国是当时最为发达的资本主义国家",a:"(C)",sol:""},{n:"(6)",q:"【2019.1】马克思、恩格斯始终站在世界无产阶级革命的前沿，他们的一生是为推翻旧世界，建立新世界而不息战斗的一生。马克思、恩格斯领导创建的世界上第一个无产阶级政党是 (A) 国际工人协会 (B) 正义者联盟 (C) 共产主义者同盟 (D) 社会主义工人国际·0032024考研政治知识精讲讲义（马原分册）",a:"(C)",sol:""},{n:"(7)",q:"【2021.1】1844年8月底，马克思和恩格斯在巴黎会面。这次会面使他们发现彼此石嘉老师提示的基本观点完全一致，于是开始了在科学理论研究和革命活动中的长期合作。马《德意志意识形态》：首次比较系统地阐述克思和恩格斯首次系统阐述历史唯物主义基本观点的著作是C历史唯物主义的基本原理。 (A) 《哲学的贫困》 (B) 《德意志意识形态》《共产党宣言》：无产阶级政党的第一个 (C) 《神圣家族》 (D) 《共产党宣言》党纲，第一次全面阐述了科学社会主义理论。",a:"(B)",sol:"【简析】1844年9月至11月，他们在巴黎合写了《神圣家族》一书（第一次合作的著作），批判青年黑格尔派的主观唯心主义。接着又在布鲁塞尔合写了《德意志意识形态》，首次系统阐述了历史唯物主义的基本观点。A正确。"},{n:"(8)",q:"【1998.文1】马克思主义是科学的，从根本上说在于它 (A) 以世界的一般规律为研究对象 (B) 始终严格地以客观事实为根据 (C) 提供了普遍适用的客观真理 (D) 形成了完整的理论体系第二，人民性。人民至上是马克思主义的政治立场。马克思主义政党把人民放在心中最高位置，一切奋斗都致力于实现最广大人民的根本利益。之所以如此，是因为人民群众是历史的创造者，是社会主义事业的依靠力量。需要指出的是，马克思主义的人民性是以阶级性为深刻基础的，是无产阶级先进性的体现。马克思主义是无产阶级的世界观，是关于无产阶级解放的学说。无产阶级解放和全人类解放是完全一致的。只有无产阶级这样的先进阶级，才能领导全人类解放的伟大事业；而无产阶级也只有解放全人类，才能最后解放自己。反对私有制社会特别是资本主义社会的经济剥削和政治压迫，建立社会主义社会，最终实现共产主义，这既是无产阶级解放的事业，也是广大人民群众和全人类解放的事业。第三，实践性。马克思主义是从实践中来，到实践中去，在实践中接受检验，并随实践而不断发展的学说。从马克思主义的使命和作用来说，它不是书斋中的学问，不是一种纯粹解释世界的学说，而是直接服务于无产阶级和人民群众改造世界的实践活动的科学理论。马克思指出：“哲学家们只是用不同的方式解释世界，而问题在于改变世界。”习近平进一步提出：“马克思主义具有鲜明的实践品格，不仅致力于科学“解释世界’，而且致力于积极‘改变世界’。”从马克思主义的内容来看，实践观点是马克思主义首要的和基本的观点，这一基本观点体现在马克思主义全部思想内容之中。马克思主义具有突出的实践精神，它始终强调理论与实践的统一，始终坚持与社会主义实际运动紧密结合。可以说，以马克思主义为指导的世界社会主义运动，本身就是马克思主义的实践形态。",a:"(B)",sol:""},{n:"(9)",q:"【1995.理1】马克思主义新世界观创立的关键在于马克思确立了 (A) 剩余价值论 (B) 阶级斗争理论 (C) 无产阶级历史使命学说 (D) 科学的实践观",a:"(D)",sol:""},{n:"(10)",q:"【2008.1】马克思主义哲学与唯心主义哲学、旧唯物主义哲学的根本区别在于( (A) 坚持人的主体地位 (B) 坚持用辩证发展的观点去认识世界 (C) 坚持物质第一性、意识第二性 (D) 坚持从客观的物质实践活动去理解现实世界第四，发展性。马克思主义是不断发展的学说，具有与时俱进的理论品质。马克思主义是时代的产物，并随着时代、实践和科学的发展而不断发展。马克思主义理论体系是开放的，它不断吸取人类最新的文明成果来充实和发展自己。马克思主义在指导人们认识世界和改造世界的过程中，在指导社会主义事业发展的过程中，不断与时代特征和各国具体实际相结合，得到丰富和发展，并形成新的理论成果。马克思主义在指导中国革命、建设、改革的过程中，形成了一系列马克思主义中国化理论成果，鲜明地体现了马克思主义创新发展的品格。当今世界和我们所处的新时代，同过去相比发生了深刻的变化。无论从国际还是从国内看，我们都面临着许多新情况新问题，需要从理论和实践上作出回答并加以解决，为此必须坚持与时俱进，继续丰富和发展.0052024考研政治知识精讲讲义（马原分册）",a:"(D)",sol:""},{n:"(11)",q:"【2022.1】中国共产党坚持马克思主义基本原理，坚持实事求是，从中国实际出发，洞察时代大势，把握历史主动，进行艰辛探索，不断推进马克思主义中国化时代化，指导中国人民不断推进伟大社会革命。习近平总书记指出：“中国共产党为什么能，中国特色社会主义为什么好，归根到底是因为马克思主义行！”马克思主义之所以“行”，根本原因在于 (A) 马克思主义具有鲜明的政治立场 (B) 马克思主义政党具有自觉的历史担当微信公众号：djky66djky (C) 马克思主义是科学的世界观和方法论（顶尖考研祝您上岸） (D) 马克思主义是无产阶级政党自我革命的武器（顶尖考研祝您上岸）0072024考研政治知识精讲讲义（马原分册）",a:"(C)",sol:""}],
  "mayuan_s6": [{n:"(1)",q:"【1997.理1】恩格斯认为，全部哲学、特别是近代哲学的重大的基本问题是djky66 (A) 哲学与人类生存活动之间的内在联系问题 (B) 人与周围世界的基本联系问题研祝您上岸） (C) 思维和存在的关系问题 (D) 关于人的本质问题",a:"(C)",sol:""},{n:"(2)",q:"【2003.1】马克思主义哲学创立后，开始出现了于我”。客观唯心主义识别关键词为理、道、宗 (A) 唯物论与唯心论的对立 (B) 可知论与不可知论的对立教、上帝、绝对观念等。 (C) 辩证法与形而上学的对立 (D) 唯物史观与唯心史观的对立·009·2024考研政治知识精讲讲义（马原分册）",a:"(D)",sol:"【简析】在马克思主义产生之前，唯物论与唯心论、辩证法与形而上学、可知论与不可知论的对立就已存在。马克思创立了唯物史观，从此开始出现唯物史观与唯心史观的对立。D正确。"},{n:"(3)",q:"【1995.理2】唯物主义一元论同唯心主义一元论对立的根本点在于 (A) 世界发展动力问题 (B) 意识本质问题 (C) 世界本质问题 (D) 实践本质问题",a:"(C)",sol:""},{n:"(4)",q:"【1998.理2】中国古代哲人苟子说：“天行有常，不为尧存，不为桀亡。”这是一种 (A) 宿命论观点 (B) 唯意志论观点 (C) 机械唯物论观点 (D) 朴素唯物论观点（二）可知论和不可知论根据对哲学基本问题第二方面的不同回答，哲学又可以划分为可知论和不可知石嘉老师提示论。可知论认为世界是可以被认识的，思维和存在具有同一性；不可知论认为世界是可知论与不可知论的种类：唯物主义可不能被人所认识或不能被完全认识的，否认思维和存在的同一性。知论、唯心主义可知论和唯心主义不可知论。",a:"(D)",sol:""},{n:"(8)",q:"【1994.理1】列宁对辩证唯物主义物质范畴的定义是通过惯、社会文化结构、思想上层建筑都是意 (A) 物质与意识的关系界定的 (B) 个别与一般的关系界定的识范畴。 (C) 哲学与具体科学的关系界定的 (D) 认识与实践的关系界定的马克思主义的物质范畴理论具有丰富而深刻的理论意义。第一，坚持了唯物主义一元论，同唯心主义一元论和二元论划清了界限。马克思主义是从物质与意识的对立统一关系中把握和规定物质的，物质最本质的规定是客观实在性，这就指明了物质对于意识的独立性和根源性，以及意识对于物质的依赖性和派生性。因为意识不过是物质的反映，不能离开物质而独立存在，所以意识不可能成为世界的另一种本原。第二，坚持了能动的反映论和可知论，有力批判了不可知论。未知世界与已知世界都是客观存在的，随着实践和科学的发展，人们对未知世界的认识将会不断扩展和深化。世界上只有尚未认识之物，没有不可认识之物。第三，体现了唯物论和辩证法的统一，克服了形而上学唯物主义的缺陷。马克思主义的物质观认为，客观实在性是物质的共同特性，既肯定了哲学物质范畴同自然科学物质结构理论的联系，又把两者区别开来，从个性中看到共性，从相对中找到绝对，从暂时中发现永恒，这是马克思主义物质观体现的唯物辩证法。第四，体现了唯物主义自然观与唯物主义历史观的统一，为彻底的唯物主义奠定了理论基础。马克思主义的物质观揭示了自然和社会的物质性，建立了统一说明自然历史过程的唯物主义原则，实现了唯物主义自然观和历史观的辩证统一。物质和物质的具体形态的关系是共性和个性的关系，也是一般与个别、普遍与特殊、抽象与具体的关系，但不是整体与部分的关系。哲学上物质范畴是对世界上的一0112024考研政治知识精讲讲义（马原分册）",a:"(A)",sol:""},{n:"(9)",q:"【1992.文6】哲学上的物质范畴与自然科学上的物质范畴的关系是 (A) 本原和派生的关系 (B) 普遍和特殊的关系 (C) 本质和现象的关系 (D) 形式和内容的关系",a:"(B)",sol:""},{n:"(10)",q:"【1996.文11《诗经》中记载：“时有风吹幡动，一僧日风动，一僧日幡动，议论不已。惠能进曰：不是风动，不是幡动，仁者心动。”这段话表明惠能关于运动的基本观点是 (A) 运动是物质的根本属性 (B) 运动与物质是不可分割的djky66 (C) 精神运动是物质运动的一种形式 (D) 精神是运动的主体",a:"(D)",sol:""},{n:"(11)",q:"【1999.文11主张“世界上除了运动着的物质之外，什么也没有”的观点，属于 (A) 否认人的意识存在的自然唯物主义 (B) 主张世界统一于物质的辩证唯物主义 (C) 否认时间与空间存在性的唯心主义 (D) 把人的意识理解成某种特殊的“精细物质”的机械唯物主义",a:"(B)",sol:""},{n:"(13)",q:"【1991.文9】“人不能两次踏进同一条河流”和“人一次也不能踏进同一条河流”，这两种说法 (A) 都是辩证法的观点 (B) 都是诡辩论的观点 (C) 前者是辩证法的观点，后者是诡辩论的观点 (D) 前者是诡辩论的观点，后者是辩证法的观点",a:"(C)",sol:""},{n:"(14)",q:"【2006.1】世界上唯一不变的是变。这一论断的含义是 (A) 变是世界的本原 (B) 世界上只有变，没有不变 (C) 变是绝对的，不变是相对的 (D) 变与不变是绝对对立的",a:"(C)",sol:""},{n:"(15)",q:"【2007.1】“风定花犹落，鸟鸣山更幽”形象地表达了动和静的辩证关系是（ (A) 静不是动，动不是静 (B) 静中有动，动中有静 (C) 动是必然的，静是偶然的 (D) 动是静的原因，静是动的结果",a:"(B)",sol:""},{n:"(16)",q:"【2013.1】有一副对联，上联“橘子洲，洲旁舟，舟行洲不行”，下联“天心阁，阁中鸽，鸽飞阁不飞”。这形象地说明了运动和静止是相互依存的。静止是 (A) 运动的衡量尺度 (B) 运动的内在原因 (C) 运动的普遍状态y66 (D) 运动的存在方式",a:"(A)",sol:""},{n:"(17)",q:"【2015.18】平衡是事物发展的一种状态。小到体操中人在平衡木上的行走，杂技中的骑车走钢丝、独轮车表演、直升机在空中的悬停等，大到人类的生存、地球的运转、天体的运行等，都是保持平衡的一种状态。世间的万事万物，之所以能不停地运动、发展、前进，一个重要原因就在于保持了平衡。要使“平衡”成为人们的“大智慧”，就要 (A) 全面理解绝对运动和相对静止的辩证关系 (B) 准确掌握辩证否定的方式和方向 (C) 精确把握事物的度 (D) 善于协调事物内部各种因素的相互关系时间和空间是运动着的物质的基本存在形式。时间是指物质运动的持续性、顺石磊老师提示序性，特点是一维性，即时间的流逝一去不复返。空间是指物质运动的广延性、伸张时空是客观的，与人无关；但时空观念是性，特点是三维性，即空间具有长、宽、高三方面的规定性。物质运动总是在一定的主观的，与人有关。时间和空间中进行的，没有离开物质运动的“纯粹”时间和空间，也没有离开时间和空间的物质运动。物质运动与时间和空间的不可分割，证明了时间和空间的客观性。具体物质形态的时空是有限的，而整个物质世界的时空是无限的。物质、运动、时间、空间具有内在的统一性，一切以时间、地点和条件为转移，具体问题具体分析，是马克思主义活的灵魂",a:"(ACD)",sol:""},{n:"(18)",q:"【1992.文7】“坐地日行八万里，巡天遥看一千河”的著名诗句所蕴含的哲理是 (A) 物质运动的客观性和时空的主观性的统一 (B) 物质运动的无限性和时空的有限性的统一 (C) 物质运动的多样性和静止的单一性的统一 (D) 物质运动的绝对性和静止的相对性的统一·0132024考研政治知识精讲讲义（马原分册）",a:"(D)",sol:""},{n:"(19)",q:"【2008.2】最近，由多国科学家组成的团队利用一台粒子加速器，让两束原子在一个圆环轨道上做高速运动，发现这些原子自身的时间确实比外界的时间慢了。这项实验进一步证明了作为物质运动存在形式的时间具有 (A) 客观性 (B) 有限性 (C) 相对性 (D) 一维性原奔流而下注人东海的“贯通东流”水系的形成年代。如果说上游的沉积物从青藏高原、四川盆地顺延而下能到达下游，这就表明长江贯通了，这就是物源示踪。我国科学家采用这一方法，研究长江中下游盆地沉积物的来源，从而判别长江上游的物质何时到达下游，间接指示了长江贯通东流的时限。他们经过10多年的研究，提出长江贯通东流的时间距今2300多万年。这一研究成果从一个侧面显示出",a:"(C)",sol:""},{n:"(22)",q:"【2019.2】“橘生淮南则为橘，生为淮北则为积，叶徒相似，其实味不同。所以然者何？水土异也。”“橘逾淮为积”说明了 (A) 事物的发展变化以时间、地点和条件为转移 (B) 事物的普遍联系是通过中介来实现的 (C) 任何具体事物都是普遍联系之网上的一个网结 (D) 事物的变化和发展是一个过程",a:"(A)",sol:""},{n:"(23)",q:"【2020.171北京时间2019年4月10日21时，“事件视界望远镜”项目在全世界多地同时召开发布会，公布了人类首次拍到的黑洞照片，这是继2015年人类通据。有科学家认为，这张看起来有点模糊的照片意义非凡，它再次验证了爱因斯坦广义相对论的预言是对的，并将进一步帮助科学家解答星系演化等一系列宇宙本质问题。人类首次“看到”黑洞正面照表明 (A) 空间的性质依赖于物质的分布及其运动状态 (B) 世界是物质的统一体 (C) 物质世界的客观存在与人的实践和认识水平有关 (D) 空间的观念随着人的认识发展而拓展·014",a:"(ABD)",sol:""},{n:"(24)",q:"【2021.171最近，科学家利用宇宙三维地图发现了迄今为止最大的宇宙结构之包含了数十万个星系、长达14亿光年的“南极墙”。类似于“南极墙”的宇宙大尺度结构，是宇宙中一些密度较高的区域。中国科学家表示，由于万有引力，密度较高的区域会产生较强的引力，将周围物质吸引过来，逐渐形成了星系以及更大尺度的结构。现代宇宙学表明，宇宙是由暗物质、暗能量主导的，但暗物质究竞是什么，目前不得而知，在“南极墙”等宇宙大尺度结构中，很可能藏匿着大量的暗物质，这是研究宇宙演化历史的重要探针。“南极墙”的发现表明 (A) 未知世界与已知世界都是客观存在的 (B) 整个物质世界的时间和空间是有限的 (C) 世界的本原是暗物质暗能量 (D) 世界上只有尚未认识之物，没有不可认识之物",a:"(AD)",sol:""},{n:"(25)",q:"【2022.19】时间是万事万物存在的刻度。1秒钟，电影放映24帧画面，猎豹在草原上飞奔28米，蜂鸟振动翅膀55次；1分钟，登山队员攀登珠峰顶峰58.3厘米，“复兴号”前进5833米。时间创造无限可能。有人努力奔跑，用全力以赴的冲刺突破极限；有人砥砺前行，以日复一日的坚守辛勤耕耘。原本匀速流动的时间，正是在生生不息的奋斗中，在昂扬奋发的进取中，确定意义、体现价值，进而定义生命的精彩、定格历史的脉动。人们在奋斗中“定义”时间，说明时间是微信公从亏：9 (A) 测量事物运动的客观尺度 (B) 物质运动的存在形式考研祝您上岸） (C) 事物运动的主观联想 (D) 与物质运动不可分割的",a:"(ABD)",sol:""},{n:"(27)",q:"【1997.理12】一位科学家说：“我们今天生活着的世界，与其说是自然世界，还不如说是人造或人为的世界。在我们周围，几乎每样东西都刻有人的技能痕迹。”这段话应理解为 (A) 人造的或人为的世界是唯一存在的世界 (B) 现实世界是人类精神的创造物djky66 (C) 人类世界是人的实践活动对象化的结果 (D) 科学技术越来越成为人类改造世界的伟大力量",a:"",sol:""},{n:"(29)",q:"【2002.理1】人类生活的现实世界是 (A) 人化自然和人类社会的统一体 (B) 客观世界和主观世界的统一体 (C) 自在自然和人化自然的统一体 (D) 人类实践活动中所形成的人类社会关系的总和",a:"(A)",sol:""},{n:"(30)",q:"【2002.理2】马克思说：“搬运夫和哲学家之间的原始差别要比家犬和猎犬之间的差别小得多。他们之间的鸿沟是分工掘成的。”这表明人的才能 (A) 与人的先天生理素质没有关联 (B) 主要来源于后天的实践 (C) 取决于人的主观努力的程度 (D) 是由人的社会政治地位决定的·016·",a:"(B)",sol:""},{n:"(31)",q:"【2003.2】在人与世界的相互作用中，人与世界同时得到了改变，并获得日益丰富的内容。造成这一变化的基础是 (A) 自然界自身的运动 (B) 人的意识的能动作用微信公众号：djky66 (C) 人的实践活动 (D) 工具的制造与使用（顶尖考研祝您上岸）",a:"(C)",sol:""},{n:"(32)",q:"【2008.17】右边这幅漫画对于我们认识人与自然关系的警示意义在于 (A) 人类过分陶醉于对自然界的胜利将受到自然界的报复忍无可忍 (B) 人与自然关系的紧张来自于不当的人类实践方式 (C) 人与自然的关系本质上是对立的 (D) 人类依附于自然是摆脱自身困境的根本出路",a:"(AB)",sol:""},{n:"(33)",q:"【2010.3】右边这张照片反映出由于气候变暖，北极冰盖融化，致使北极熊无处可去的场景，颇具震撼力。它给我们地球上的人类发出的警示是 (A) 人与自然的关系成为人与人之间一切社会关系的核心 (B) 生态失衡已成为自然界自身周期演化不可逆转的趋势 (C) 自然地理环境已成为人类社会发展的根本决定力量 (D) 生态环境已日益成为人类反思自身活动的重要前提",a:"(D)",sol:""},{n:"(34)",q:"【2007.18】某地乡村公路边有很多柿子园。金秋时节，农民采摘柿子时，最后总要在树上留一些熟透的柿子。农民们说，这是留给喜鹊的食物。每到冬天，喜鹊都在果树上筑巢过冬，到冬天也不飞走，整天忙着捕捉果树上的虫子，从而保证了来年柿子的丰收。从这个实例中，我们受到的启示是 (A) 事物之间有其固有的客观联系 (B) 人们可以发现并利用规律来实现自己的目的 (C) 人与自然的关系是相互利用的关系 (D) 保持生态系统平衡是人类生存发展的必要条件0172024考研政治知识精讲讲义（马原分册）",a:"(ABD)",sol:""},{n:"(35)",q:"【2021.18】人的身体是抗击病毒的“机器”。当病原体进入人体，人会发烧，升高的体温刺激免疫系统打败病毒。在理想的情况下，热量创造了一个环境，让病原体难以生存。科学家研究发现，随着自然界的温度不断升高，病原体生存的环境也在整体升温，在这种情况下，它们更加能够适应人体发烧的体温。一旦病原体适应更高的温度，人的免疫系统就无法发挥作用。人的免疫系统与自然环境之间的关系表明 (A) 人类只能适应自然环境变化而不能改变自然环境 (B) 自然环境对人类发展具有决定性作用 (C) 自然环境是人类生存和发展的重要前提 (D) 人类在受自然环境制约的同时也改变自然环境",a:"(CD)",sol:""},{n:"(36)",q:"【2022.2】党的十八大以来，我国从中西部22个省份有劳动能力的建档立卡贫困人口中选聘了110.2万名生态护林员，走出了一条生态补偿脱贫的新路子，实现了生态保护和脱贫增收“双赢”，充分体现了“人不负青山，青山定不负人”的深刻哲理。“人不负青山，青山定不负人”表明 (A) 生产力包括自然要素，合理开发自然促进社会发展 (B) 人与自然是同一的，自然能够自发满足人的要求 (C) 人是自然的一部分，人的发展只能适应自然的变化 (D) 人能动改造自然，自然能动补偿人的劳动",a:"(A)",sol:""},{n:"(38)",q:"【1996.理1】人工智能的出现对哲学意识论的意义是 (A) 否定了意识对物质的能动性 (B) 根本改变了人类意识活动中的主体性 (C) 降低了人在意识活动中的主体性 (D) 表明意识活动与其他物质形式的同一性",a:"(D)",sol:""},{n:"(40)",q:"【1999.文2；理1】“观念的东西不外是移入人的头脑并在人的头脑中改造过的物质的东西而已。”这个命题表明 (A) 意识是人脑中特有的物质djky66 (B) 人脑是意识的源泉 (C) 观念的东西和物质的东西没有本质上的区别 (D) 意识是客观存在的主观映象研祝您上岸）",a:"(D)",sol:""},{n:"(41)",q:"【2001.文2】人类创造的自然语言和人工语言 (A) 是人类的主观意识 (B) 既非物质，也非意识 (C) 是人类意识的物质外壳 (D) 是意识的内容",a:"(C)",sol:""},{n:"(42)",q:"【2007.17】关于龙的形象，自古以来就有“角似鹿、头似驼、眼似兔、项似蛇、腹似蜃、鳞似鱼、爪似鹰、掌似虎、耳似牛”的说法，这表明( (A) 观念的东西是转入人脑并在人脑中改造过的物质的东西 (B) 一切观念都是现实的模仿 (C) 虚幻的观念也是对事物本质的反映 (D) 任何观念都可以从现实世界中找到其物质原型",a:"(AD)",sol:""},{n:"(43)",q:"【2010.171从上世纪70年代至今，商务印书馆先后出版了多个版本的《新华字典》。删除了一些旧的词条，增加了一些新的词条，并对若干词条的词义作了修改。例如1971年版对“科举”这个词的解释是：“从隋唐到清代的封建王朝为维护其反动统治而设立分科考选文武官更后备人员的制度”，1992年版删去“反动”二字，1998年版又删去“为维护其统治而设”。再如1971年版在解释“雉”就是“野鸡”之后，紧跟着说“肉可以吃，羽毛可以做装饰品”。1992年版、1998年版也一样，直到2008年版删去了这句话。一本小字典，记载着词语的发展变化，也记录着时代前进的印证。字典词条释义的变化表明人们的意识（ (A) 是客观世界的能动反映 (B) 取决于词语含义的改变 (C) 随着社会生活变化而变化 (D) 需要借助语言这一物质外壳表达出来·0192024考研政治知识精讲讲义（马原分册）",a:"(ACD)",sol:""},{n:"(44)",q:"【2017.2】有人认为，既然人的意识是对客观外部世界的反映，那么人脑里的“鬼”“神”意识就是对外在世界上鬼、神真实存在的反映。这种观念的错误在于 (A) 夸大意识的能动作用 (B) 把意识看成是物质的产物 (C) 认为意识是对存在的直观反映 (D) 混淆了人类意识自然演化的阶段（二）意识对物质具有反作用物质决定意识，意识对物质具有反作用，这种反作用就是意识的能动作用。意识的能动作用主要表现在：第一，意识具有目的性和计划性。人的整个实践过程，就是围绕意识活动所构建的目标和蓝图来进行的。第二，意识具有创造性。人的意识不仅采取感觉、知觉、表象等形式，反映事物的外部现象，而且运用概念、判断、推理等形式，对感性材料进行加工制作和选择建构，在思维中构造一个现实中所没有的观念世界。第三，意识具有指导实践改造客观世界的作用。意识的能动作用不限于从实践中形成一定的思想，形成活动的目的、计划、方法等观念的东西，更重要的在于以这些观念的东西为指导，通过实践使之一步步变为客观现实。改变世界或创造世界不仅意味着强化客观世界的变化过程，而且意味着创造出世界上原来所没有的东西，即没有人的参与永远也不可能出现的东西。第四，意识具有调控人的行为和生理活动的作用。现代科学和医学实验证明，意识、心理因素能够对人的行为选择和健康状况产生重要影响。俗话说的“笑一笑十年少，愁一愁白了头”多少反映了这个道理。",a:"(C)",sol:""},{n:"(45)",q:"【1991.文71先有工程设计图，然后施工建成大厦。这一事实说明 (A) 意识产生物质 (B) 意识转化为物质 (C) 意识决定物质 (D) 意识创造物质",a:"(B)",sol:""},{n:"(47)",q:"【2000.文11人的意识不仅反映客观世界，并且创造客观世界。这一命题表明意识对物质具有 (A) 决定性 (B) 预见性 (C) 能动性 (D) 主动性020",a:"(C)",sol:""},{n:"(48)",q:"【2000.理1】中国古代哲学家苟子说：“心不在焉，则白黑在前而目不见，雷鼓在侧而耳不闻。”这段话表明人的意识具有 (A) 客观性 (B) 能动性 (C) 对象性 (D) 任意性",a:"(B)",sol:""},{n:"(51)",q:"【2003.3】人的视觉感官有感觉外界物体的光和颜色的功能。可见光的波长范围一般是380nm（纳米）到780nm，称为可见光谱。在可见光谱范围内，不同波长的辐射使人感觉到不同的颜色，一般来说，700nm为红色，580nm为黄色，510nm为绿色，470nm为蓝色，400nm为紫色。这种现象表明 (A) 人只能认识外界物体作用于感官形成的感觉 (B) 人的感觉所具有的生理阀限是人认识能力的界限 (C) 人的感觉中包含着对外界事物信息的选择、加工和转换 (D) 人所形成的关于事物的感觉是人自身生理活动的结果",a:"(C)",sol:""},{n:"(52)",q:"【2005.1】广大农民在致富奔小康的过程中深切体会到：“要富口袋，先富脑袋。”这一说法在哲学上的含义是 (A) 精神是第一性的，物质是第二性的 (B) 精神的力量可以变成物质的力量 (C) 精神的力量可以代替物质的力量 (D) 先有精神，后有物质",a:"(B)",sol:""},{n:"(53)",q:"【2009.1】物质和意识的对立只有在非常有限的范围内才有绝对的意义，超过这个范围便是相对的了。这个范围是指 (A) 物质和意识何者为第一性 (B) 物质和意识是否具有同一性 (C) 物质和意识何者更为重要 (D) 物质和意识何者与社会生活的关系更密切0212024考研政治知识精讲讲义（马原分册）",a:"(A)",sol:"【简析】本题题干引用的是列宁的话，其意思是说，物质和意识的对立只有在何者为第一性的范围内才有绝对的意义，超出这个范围，其对立便是相对的。因此，正确答案是A。"},{n:"(54)",q:"【2009.17】近一年多来，由美国次贷危机引发的金融危机迅速在全球蔓延。在危机面前，人们应该积极主动应对，化“危”为“机”。下列名言中，符合意识能动性原理的是 (A) 信心比黄金更重要 (B) 我们唯一恐惧的就是恐惧本身 (C) 问题与解决问题的方法是同时产生的 (D) 事不避难，知难不难",a:"(ABCD)",sol:""},{n:"(55)",q:"【1996.文2】辩证唯物主义认为事物发展的规律是 (A) 思维对事物本质的概念和反映 (B) 用来整理感性材料的思维形式 (C) 事物内在的本质的稳固的联系 (D) 事物联系和发展的基本环节",a:"(C)",sol:""},{n:"(58)",q:"【2010.20】1989年，时任美国国务院顾问的弗朗西斯·福山抛出了所谓的“历史终结论”，认为西方实行的自由民主制度是“人类社会形态进步的终点”和“人类最后一种统治形式”。然而，20年来的历史告诉我们，终结的不是历史，而是西方的优越感。就在柏林墙倒塌20年后的2009年11月9日，BBC公布了一份对27国民众的调查，结果半数以上的受访者不满资本主义制度。此次调查的主办方之一的“全球扫描”公司主席米勒对媒体表示，这说明随着1989年柏林墙的倒塌，资本主义并没有取得看上去的压倒性胜利，这一点在这次金融危机中表现得尤其明显。“历史终结论”的破产说明 (A) 社会规律和自然规律一样都是作为一种盲目的无意识力量起作用石磊老师提示 (B) 人类历史的发展的曲折性不会改变历史发展的前进性社会规律是通过人的有意识的活动实现的 (C) 一些国家社会发展的特殊形式不能否定历史发展的普遍规律（自觉的）。 (D) 人们对社会发展某个阶段的认识不能代替对社会发展的整个过程的认识自然规律是作为一种盲目的无意识力量起作用（自发的）。",a:"(BCD)",sol:""},{n:"(59)",q:"【2014.2】俄国早期马克思主义理论家普列汉诺夫说，绝不会有人去组织一个“月食党”以促进或阻止月食的到来，但要进行社会革命就必须组织革命党。这是因为社会规律与自然规律有所不同，它是( (A) 通过人的有意识的活动实现的 (B) 由多数人的意志决定的 (C) 比自然规律更易于认识的规律 (D) 不具有重复性的客观规律·0232024考研政治知识精讲讲义（马原分册）",a:"(A)",sol:""},{n:"(60)",q:"【2017.1】某地区进入供暖季后常常出现雾霾，而一旦出现大风天气或等到春暖花开后，雾霾就会散去或减少。从该地区较长时间的数据变化看，经过人们努力治霾，污染物排放总量在持续走低；但在某些时段，环境空气质量污染指数会迅速攀升，甚至“爆表”。这种看似“矛盾”的现象，凸显了大气污染防治的一大特点：天帮忙很重要，但人努力才是根本。“人努力”与“天帮忙”之间的关系对我们正确处理主观能动性和客观规律之间的辩证关系的启示是 (A) 尊重事物的客观规律是正确发挥主观能动性的前提 (B) 人类有意识的思想活动是掌握客观规律的根本前提 (C) 认识活动是客观规律性与主观能动性相统一的基础 (D) 尚未认识的外在自然规律对人的实践活动起着至关重要的作用",a:"(A)",sol:""},{n:"(61)",q:"【2021.2】习近平强调，“历史是最好的教科书”，“历史的经验值得注意，历史的教训更应引以为戒”，“中国革命历史是最好的营养剂”。人们能从历史中汲取经验教训，是因为 (A) 历史总是在循环往复中不断向前发展 (B) 历史规律和自然规律存在着惊人的相似性 (C) 人类历史发展存在着不以人的意志为转移的规律 (D) 人类已经完全掌握了历史发展的内在规律",a:"(C)",sol:""},{n:"(62)",q:"【2022.17】在深人推动黄河流域生态保护和高质量发展座谈会上，习近平总书记谈及水资源和发展的关系时，以传统名吃“羊肉泡馍”作形象比喻，强调要全方位贯彻“四水四定”（以水定城、以水定地、以水定人、以水定产）原则，精打汤泡多少馍”蕴含的哲学道理是 (A) 创造条件，充分发挥意识能动性 (B) 一切从实际出发，实事求是 (C) 因地制宜，因时制宜 (D) 尊重规律，把握适度原则",a:"(BCD)",sol:""},{n:"(63)",q:"【1995.文1】彻底的唯物主义一元论的根本要求是微信公众号：djky66 (A) 承认世界是多样的统一 (B) 承认物质对意识的根源性 (C) 坚持一切从实际出发 (D) 反对一切形式的二元论（顶尖考研祝您上岸）",a:"(C)",sol:""},{n:"(64)",q:"【2019.17】虚拟现实技术是一种运用计算机仿真系统创建多源信思融合的交互式三维动态实景以及动作仿真的技术，可以给使用者提供沉浸性、多感知性、交互性的互动体验。虚拟现实技术所构造的虚拟环境说明( (A) 物质世界不再具有客观实在性 (B) 物质世界的存在形式具有多样性 (C) 信息是独立于物质和意识的第三种存在状态 (D) 人们可以通过实践创造出自然界原本不存在的现实状态",a:"(BD)",sol:""},{n:"(65)",q:"【2022.181人类历史上的每一次科技革命都与材料的发展息息相关，而新材料的研制却是颇为不易的。人工智能可以借助数据共享，对先进材料的物理化学性质进行预测、筛选，从而加快新材料的合成和生产。作为人工智能的一个分支，机器学习算法在辅助新材料设计时尤为“得力”，其工作过程主要包括“描述符”生成、模型构建和验证、材料预测、实验验证等步骤。人工智能辅助新材料研发的过程表明( (A) 科学研究能够任意改变物质的性质和结构 (B) 人工智能能够取代人类对物质世界的认识 (C) 人类对于物质的认识是一个不断深化的过程 (D) 具体的物质结构和性质的变化并不改变世界的物质性0252024考研政治知识精讲讲义（马原分册）",a:"(CD)",sol:""},{n:"(67)",q:"【2013.2】一位机械工程专家讲过这样一件事：“文革”中，他在农场劳动，有一天领导要他去割羊草。他没养过羊，怎么认得羊草呢？但脑子一转办法就来了。他把羊牵出去，看羊吃什么就割什么。不到半天就割回了羊草。这位专家之所以回是，真， (A) 主观联系 (B) 必然联系 (C) 因果联系 (D) 本质联系·026·",a:"(C)",sol:""},{n:"(68)",q:"【2018.17】2017年6月，我国科学家利用“墨子号”量子科学实验卫星在国际上率先成功实现了千公里级的星地双向量子纠缠分发。“量子纠缠”就是两个（或多个）粒子共同组成的量子状态，无论粒子之间相隔多远，测量其中一个粒子( (A) 物质世界联系的客观性和普遍性 (B) 事物联系的主观性和偶然性 (C) 事物联系的复杂性和多样性 (D) 世界的真正统一性在于它的物质性",a:"(ACD)",sol:""},{n:"(69)",q:"【2012.17】“沉舟侧畔千帆过，病树前头万木春。”辩证法认为发展的实质是新事物的产生和旧事物的灭亡。新生事物必然取代旧事物，从根本上说，是因为( (A) 新生事物产生于旧事物之后，是新出现的事物 (B) 新生事物具有新的结构和功能，能适应已经变化了的环境和条件 (C) 新生事物是对旧事物的扬弃，并添加了旧事物所不能容纳的新内容 (D) 在社会历史领域内，新生事物符合广大人民群众的根本利益和要求",a:"(BCD)",sol:""},{n:"(70)",q:"【2007.19】2006年7月12日凌晨，刘翔在瑞士洛桑国际田联超级大奖赛男子110米栏比赛中，以12秒88勇夺冠军，打破了由英国名将科林·杰克逊保持了13年之久的12秒91的世界纪录。科林在谈起自己已被打破的纪录时，没有一丝沮丧：“我一点也不失望，正相反，我感到非常兴奋。”他说：“纪录本来就是用来被打破的。”这在哲学上的启示是 (A) 创新是永无止境的 (B) 不断超越前人是历史发展的规律 (C) 凡是在历史上产生的都要在历史上灭亡 (D) 一切事物都是作为过程而存在，作为过程而发展",a:"(ABCD)",sol:""},{n:"(71)",q:"【2015.17】母质、气候、生物、地形、时间是土壤形成的五大关键成土因素。母质是土壤形成的物质基础和初始无机养分的最初来源。气候导致矿物的风化和合成、有机质的形成和积累、土壤中物质的迁移、分解和合成。生物包括植物、动物和微生物等，是促进土壤发生发展最活跃的因素。地形可以使物质在地表进行再分配，使土壤及母质在接受光、热、水等条件方面发生差异。时间是阐明土壤形成发展的历史动态过程，母质、气候、生物和地形等对成土过程的作用随着时间的延续而加强。土壤的生成过程说明 (A) 事物的产生是多种因素相互作用的结果 (B) 时间是物质运动的存在形式 (C) 事物总是作为过程而存在 (D) 事物的发展总是呈现出线性上升的态势028",a:"(ABC)",sol:""},{n:"(72)",q:"【1994.理2】唯物辩证法认为 (A) 必然性意义重大，偶然性可以忽略不计 (B) 必然性是可以预见的，偶然性是无法认识的 (C) 必然性是不可选择的，偶然性是可以选择的 (D) 必然的东西是偶然的，偶然的东西是必然的·029·2024考研政治知识精讲讲义（马原分册）",a:"(D)",sol:""},{n:"(73)",q:"【2001.文；理1】“只要知道自然界一切组成部分的相对位置和全部作用，一亿年以前的情况和一亿年以后的状况，都可以精确无误地演算出来，因为未来的一切早就在宇宙诞生时便已完全被确定了。”这是石嘉老师提示 (A) 唯心主义决定论的观点 (B) 辩证唯物主义的观点非决定论：只看到偶然； (C) 非决定论的观点 (D) 机械决定论的观点决定论：只看到必然。（三）原因与结果原因和结果是揭示事物引起和被引起关系的一对范畴。在事物的普遍联系中，引起某种现象的现象就是原因，而被某种现象所引起的现象就是结果。原因和结果是相互区别的。在一个具体的因果联系中，原因就是原因，结果就是结果，原因在前，结果在后，二者不能混淆和颠倒。如果“倒因为果”或者“倒果为因”，就会歪曲事实，得出荒谬的结论。原因和结果是相互依存和相互转化的。在事物因果联系的长链中，任何原因都必然引起一定的结果，没有“无果之因”；任何结果都是由一定的原因引起的，没有“无因之果”；一种现象在一种联系中是原因，在另一种联系中则是结果，反之亦然。原因和结果的辩证关系能够指导我们的认识和实践活动。只有全面把握事物的因果关系，我们才能通过自觉的努力，消除不利的原因，使因果关系运动朝着有利于人的发展的方向运行，从而达到我们所需要的结果。",a:"(D)",sol:""},{n:"(74)",q:"【1992.文8】唯物辩证法的因果联系是指石磊老师提示 (A) 一切前后相继的现象之间的联系 (B) 一切同时并存的现象之间的联系在此之前并不等于由此之故。 (C) 引起和被引起的现象之间的联系 (D) 反映和被反映的现象之间的联系（四）现实与可能现实与可能是反映事物的过去、现在和将来的相互关系的范畴。现实是指相互联系着的实际存在的事物的综合。可能是指包含在事物中并预示事物发展前途的种种趋势，是潜在的尚未实现的东西。现实与可能相互区别。可能不等于现实，现实已经不是可能。现实是当下的客观存在，标志着事物的当前状况；可能是事物潜在的趋势，标志着事物的发展方向。现实与可能相互转化。一方面，现实蕴藏着未来的发展方向，会不断产生出新的可能；另一方面，可能包含着发展成为现实的因素和根据，一旦主客观条件成熟，可能就会转化为现实。发展就是现实与可能相互转化的过程。在实践中正确把握现实与可能的辩证关系，既涉及对现实的评价，也涉及对未来的认识。这就要求我们一方面立足现实，对可能性作出全面的分析和预判；另一方面着眼长远，防止坏的可能变为现实，同时善于创造条件，促使好的可能获得实现。",a:"(C)",sol:""},{n:"(75)",q:"【2007.2】“挟泰山以超北海，语人日吾不能，是诚不能也。为长者折技，语人日石磊老师提示吾不能，是不为也，非不能也。”《孟子》中的这段话启示我们，做事情时要区分请思考：不可能是不是一种可能？可能性和不可能性，二者的区别在于 (A) 人的主观努力程度 (B) 对人是否有利 (C) 现实中有无根据和条件 (D) 现实中的根据和条件是否充分（五）内容与形式内容与形式是揭示事物内在要素同这些要素的结构和表现方式的关系范畴。内容是指构成事物的一切要素的总和，是事物存在的基础。形式是指把诸要素统一起来的结构或表现内容的方式。030·",a:"(C)",sol:""},{n:"(78)",q:"【1999.理2】在哲学史中我们可以看到，各种唯心主义派别之间的差异和矛盾，常常有利于唯物主义的发展。这一事实说明 (A) 矛盾一方克服另一方促使事物发展 (B) 矛盾一方的发展可以为另一方的发展提供条件 (C) 矛盾双方中每一方的自身矛盾，都可以为另一方的发展所利用 (D) 矛盾双方的融洽促使事物发展",a:"(C)",sol:""},{n:"(83)",q:"【1993.文3】事物发展过程中的“度”是指 (A) 事物质变的关节点 (B) 事物质变的临界点（顶尖考研祝您上岸） (C) 事物保持一定质的量的限度 (D) 事物保持一定量的质的限度",a:"(C)",sol:""},{n:"(84)",q:"【1997.理2】在工作中防止“过”或“不及”的关键在于 (A) 抓住事物的主要矛盾 (B) 认识事物的量 (C) 确定事物的质 (D) 把握事物的度",a:"(D)",sol:""},{n:"(85)",q:"【2001.理2】鲁迅在评《三国演义》时说：“至于写人，亦颇有失，以致欲显刘备之长厚而似伪，状诸葛之多智而近妖。”这一评述所蕴含的哲理是 (A) 要区分事物的两重性 (B) 要把握事物的度 (C) 对事物既要肯定，又要否定 (D) 要把事物看作一个整体",a:"(B)",sol:""},{n:"(86)",q:"【2011.11我国数学家华罗庚在一次报告中以“一支粉笔多长为好”为例来讲解他所倡导的优选法。对此，他解释道：“每支粉笔都要丢掉一段一定长的粉笔头，单就这一点来说，愈长愈好。但太长了，使用起来很不方便，而且容易折断。每断一次，必然多浪费一个粉笔头，反而不合适。因而就出现了粉笔多长最合适的问题一这就是一个优选问题。”所谓优选问题，从辩证法的角度看，就是要 (A) 注重量的积累 (B) 保持事物质的稳定性 (C) 坚持适度原则 (D) 全面考虑事物属性的多样性·0352024考研政治知识精讲讲义（马原分册）",a:"(C)",sol:""},{n:"(87)",q:"【2016.1】《百喻经》中有一则寓言：有一个愚人到别人家去做客，他嫌菜没有味道，主人就给他加了点盐。菜里加盐以后，味道好极了。愚人就想：“菜之所以鲜美，是因为有了盐。加一点点就如此鲜美，如果加更多的盐，岂不更加好吃？”回家之后，他把一把盐放进嘴里，结果又苦又咸。这则寓言给我们的启示是 (A) 持续的量变会引起事物发生质的变化 (B) 在认识和处理问题时要掌握适度的原则 (C) 不可能通过一些现象而去认识某个事物的本质 (D) 在事物的发展过程中要时时注意事物的自我否定（二）事物发展的量变和质变及其辩证关系量变和质变。由于任何事物都是质和量的统一体，因而事物的变化表现为量变和质变两种运动状态。量变是事物数量的增减和组成要素排列次序的变动，是保持事物的质的相对稳定的不显著的变化，体现了事物渐进过程的连续性。质变是事物性质的根本变化，是事物由一种质态向另一种质态的飞跃，体现了事物渐进过程和连续性的中断。区分量变和质变的根本标志是事物的变化是否超出度，在度的范围内的变化是量变，超出度的变化是质变。",a:"(B)",sol:""},{n:"(88)",q:"【1992.文9】区分事物发展过程中量变和质变的根本标志是djky66 (A) 事物的变化是否迅速 (B) 事物的变化过程中是否有部分质变 (C) 事物的变化是否超过度的范围 (D) 事物的变化是否显著量变和质变的辩证关系。第一，量变是质变的必要准备。任何事物的变化都有一个量变的积累过程，没有量变的积累，质变就不会发生。第二，质变是量变的必然结果。单纯的量变不会永远持续下去，量变达到一定程度必然引起质变。第三，量变和质变是相互渗透的。一方面，在总的量变过程中有阶段性和局部性的部分质变；另一方面，在质变过程中也有旧质在量上的收缩和新质在量上的扩张。量变和质变是相互依存、相互贯通的，量变引起质变，在新质的基础上，事物又开始新的量变，如此交替循环，形成事物质量互变的规律性。量变质变规律揭示了事物发展的形式和状态，体现了事物发展的渐进性和飞跃性的统一。量变质变规律的方法论意义。首先，它揭示了事物发展过程是连续性和阶段性的统一，这是无产阶级政党制定路线、方针、政策的重要理论依据。其次，它是我们分析社会发展形式的基本理论工具，对于我们正确处理社会主义改革、发展、稳定的关系具有指导意义。最后，它是指导我们从事一切实践活动的重要思想原则。在实际工石磊老师提示作和生活中，要把远大的理想目标和科学的求实精神结合起来，把敢想、敢闯的革命精神和脚踏实地的工作作风结合起来，既反对因循守旧、止步不前，又反对急躁、陷量变必然引起质变是正确的。量变必然导致质变是错误的。于空想。",a:"(C)",sol:""},{n:"(90)",q:"【2010.2】有一则言：“在溪水和岩石的斗争中，胜利的总是溪水，不是因为力量，而是因为坚持。”“坚持就是胜利”的哲理在于 (A) 必然性通过偶然性开辟道路 (B) 肯定中包含着否定的因素 (C) 量变必然引起质变 (D) 有其因必有其果",a:"(C)",sol:""},{n:"(91)",q:"【2012.2】有这样一道数学题：“90%×90%×90%×90%×90%=？”其答案是约59%。90分看似是一个非常不错的成绩，然而，在一项环环相扣的连续不断的工作中，如果每个环节都打点折扣，最终得出的成绩就是不及格。这里蕴含的辩证法原理是 (A) 肯定中包含否定 (B) 量变引起质变 (C) 必然性通过偶然性开辟道路 (D) 可能和现实是相互转化的",a:"(B)",sol:""},{n:"(93)",q:"【1995.文2】唯物辩证法的否定之否定规律揭示了事物发展的 (A) 方向和道路 (B) 形式和状态 (C) 结构和功能 (D) 源泉和动力V6",a:"(A)",sol:""},{n:"(94)",q:"【1998.理3】事物内部的肯定方面和否定方面的对立统一运动，从表现形式上看祝您上岸） (A) 是事物自我完善和发展的过程 (B) 是新事物战胜旧事物的过程 (C) 是螺旋式上升或波浪式前进的过程 (D) 是不断周而复始的循环过程",a:"(C)",sol:""},{n:"(95)",q:"【2000.理3】主观辩证法与客观辩证法的关系是微信公众号：djky66 (A) 反映与被反映的关系 (B) 唯心主义与唯物主义的关系 (C) 抽象与具体的关系 (D) 唯心辩证法与唯物辩证法的关系（顶尖考研祝您上岸）",a:"(A)",sol:""}],
  "mayuan_s10": [{n:"(2)",q:"【2002.文1】随着科学技术的发展，人类已经制造出诸如醋酸纤维、聚苯乙烯、合成橡胶等自然界原本不存在的化合物，其数量已达数百万种。这一情况说明 (A) 物质世界是人类创造的 (B) 人类通过实践将“自在之物”转化为“为我之物” (C) 物质世界依赖于人的意识而存在 (D) 人造物质可以脱离天然物质而存在",a:"",sol:""},{n:"(3)",q:"【2006.2】“只有音乐才能激起人的音乐感；对于没有音乐感的耳朵说来，最美的音乐也毫无意义”。这表明 (A) 人的认识是主体与客体相互作用的过程和结果 (B) 人的感觉能力决定认识的产生和发展 (C) 人的认识能力是由人的生理结构决定的 (D) 事物因人的感觉而存在0472024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(4)",q:"【2017.17】生物学史，可以说是显微镜的发展史。17世纪中叶，英国科学家使用诞生不久的显微镜观察软未塞，发现了植物细胞，开启了近现代生物学的大门。此后，显微镜的放大能力和成像质量不断提升，人类对细胞的认知也随之深刻和全面。20世纪中叶，科学家们利用X射线晶体学发现了DNA（脱氧核糖核酸）双螺旋结构，人类的观察极限从亚细胞结构推向了分子结构。我国科学家的重要科研成果“剪接体的高分辨率三维结构”的背后，也站着一个默默无闻的英雄一一冷冻电子显微镜。显微镜在生物科学发现中的作用表明 (A) 探索未知世界的科学实验是人类最基本的实践活动 (B) 实践的主体和客体正是依靠中介系统才能够相互作用 (C) 人类认识水平的提高与实践条件的进步有着直接的关系 (D) 实践主体、客体和中介三者的有机统一构成实践的基本结构",a:"",sol:""},{n:"(6)",q:"【2005.3】未来学家尼葛洛庞蒂说：“预测未来的最好办法就是把它创造出来。”从认识与实践的关系看，这句话对我们的启示是 (A) 认识总是滞后于实践考研视 (B) 实践是认识的先导 (C) 实践高于认识 (D) 实践与认识是合一的",a:"",sol:""},{n:"(7)",q:"【2006.3】温家宝总理在给一位国务院参事的回信中，引用了两句诗：“知屋漏者在宇下，知政失者在朝野。”这一古训蕴含的哲理是 (A) 人的经验是判断是非得失的根本尺度 (B) 直接经验比间接经验更重要 (C) 感性认识高于理性认识 (D) 人民群众的直接经验即实践是认识的重要基础者，必然对书本也是无知的。”与这句话在内涵上相一致的名言还有C",a:"",sol:""},{n:"(9)",q:"【2011.17】1971年，迪土尼乐园的路径设计获得了“世界最佳设计”奖，设计师格罗培斯却说：“其实那不是我的设计”。原因是在迪士尼乐园主体工程完工后，格罗培斯暂停修筑乐园里的道路，并在空地上撒上草种。五个月后，乐园里绿草茵茵，草地上被游客踏出了不少宽窄不一的小路。格罗培斯根据这些行人踏出来的小路铺设了人行道，成了“优雅自然、简捷便利、个性突出”的优秀设计。格罗培斯的设计智慧对我们认识和实践活动的启示是 (A) 要从生活实践中获取灵感 (B) 要尊重群众的实际需求 (C) 不要对自然事物做任何改变 (D) 要对事物本来面目做直观反映0492024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(10)",q:"【2015.1】中国工程院院士袁隆平曾结合自己的科研经历，语重心长地对年轻人说：“书本知识非常重要，电脑技术也很重要，但是书本电脑里种不出水稻来，只有在田里才能种出水稻来。”这表明 (A) 实践是人类认识的基础和来源 (B) 实践水平的提高有赖于认识水平的提高 (C) 理论对实践的指导作用没有正确与错误之分 (D) 由实践到认识的第一次飞跃比认识到实践的第二次飞跃更重要",a:"",sol:""},{n:"(12)",q:"【1992.文10】辩证唯物主义认为，认识的本质是的根本区别在于：一是把实践的观点引入 (A) 主体对各种认识要素的建构 (B) 主体通过实践对客体的能动反映认识论；二是把辩证法应用于反映论考察 (C) 主体对客体本质的内省 (D) 主体对客体信息的选择认识的发展过程。",a:"(B)",sol:""},{n:"(14)",q:"【1999.文31法国科学家路易·巴斯德说：“在观察事物之际，机遇偏爱有准备的头脑。”这句话强调了( (A) 人们对每一件事物都要细心观察 (B) 人们在认识事物时要有理性的指导 (C) 人们获得感性经验的重要性 (D) 人们要充分发挥主观能动性",a:"(B)",sol:""},{n:"(16)",q:"【2012.11恩格斯说：“鹰比人看得远得多，但是人的眼晴识别东西远胜于鹰。狗比人具有敏锐得多的嗅觉，但是它连被人当作各种物的特定标志的不同气味的百分之一也辨别不出来。”人的感官的识别能力高于动物，除了人脑及感官发育得更加完善之外，还因为( (A) 人不仅有感觉还有思维 (B) 人不仅有理性还有非理性 (C) 人不仅有直觉还有想象 (D) 人不仅有生理机能还有心理活动（三）从感性认识上升到理性认识，必须具备的两个基本条件第一，投身实践，深入调查，获取十分丰富和合乎实际的感性材料。这是实现由感性认识上升到理性认识的基础。因为“理论创新只能从问题开始。从某种意义上说，理论创新的过程就是发现问题、筛选问题、研究问题、解决问题的过程”。第二，必须经过思考的作用，运用理论思维和科学抽象，将丰富的感性材料加以去粗取精、去伪存真、由此及彼、由表及里的处理加工，形成概念和理论的系统。之所以如微信公众号：djky66此，是因为“理论思维的起点决定着理论创新的结果”。（四）认识过程中的理性因素和非理性因素（顶尖考研祝您上岸）在认识活动中，实践起了决定性的作用，但无论是实践活动还是认识活动，都是人的有意识的活动，在这些活动中，人的理智、情感和意志是融合在一起的。认识过程主要是理性思维的过程，同时又包含非理性因素的参与。理性因素是指人的理性直观、理性思维等能力，它在认识活动中的作用主要有三个：第一，指导作用。人的认识活动是有目的地探求真理的活动，无论是认识课题的选择、认识工具的使用，还是认识结果的总结和概括，都离不开理性因素的指导。第二，解释作用。借助科学理论，可以对纷繁复杂、瞬息万变的现象作出系统的说明。第三，预见作用。以科学理论为依据的科学预见比起以日常经验为基础的经验推测，具有更大的可靠性。非理性因素主要是指认识主体的情感和意志。人作为认识主体是知、情、意的统一整体，不仅有认知能力，还有情感和意志。从广义上看，非理性因素还包括认识能石嘉老师提示力中具有不自觉、非逻辑性等特点的认识形式，如联想、想象、猜测、直觉、顿悟灵感等。非理性因素虽不属于人的认识能力，但对人的认识活动的发生与停止，对主我们既肯定理性因素在认识活动中的主导作用，同时也承认并重视非理性因素的重体认识能力的发挥与抑制起着重要的控制和调节作用。非理性因素对于人的认识能力要作用。和认识活动具有激活、驱动和控制作用，美好的心境、坚忍的意志、饱满的热情等，往往能调动主体的精神力量去努力实现实践的目标。所以，我们既要重视理性因素的作用，又应当充分发挥非理性因素的积极作用。马克思主义哲学既肯定理性因素在认识活动中的主导作用，强调非理性因素要受理性因素的制约，同时也承认并重视非理性因素的重要作用，它全面分析了非理性因素在认识中的积极作用和可能产生的消极影响，从而同非理性主义划清了界限",a:"(A)",sol:""},{n:"(17)",q:"【2014.1】爱迪生发明电灯之前做了两千多次实验，有个年轻的记者曾经问他为什么遭遇这么多次失败。爱迪生回答：“我一次都没有失败。我发明了电灯。这只是一段经历了两千步的历程。”爱迪生之所以说“我一次都没有失败”，是因为他把每一次实验都看作 (A) 对事物规律的正确反映石磊老师提示 (B) 整个实践过程中的一部分 (C) 实践中可以忽略不计的偶然挫折马克思辩证唯物主义认识论认为：实践是人类能动地改造世界的客观物质性活动。 (D) 认识中所获得的相对真理djky66认识是主体在实践基础上对客体的能动反（二）认识和实践的具体的历史的统一映。实践和认识是辩证统一的：实践决定从实践到认识、从认识到实践，实践、认识、再实践、再认识，认识运动不断反认识，是认识发生的现实基础，认识对实复和无限发展，这是人类认识运动的辩证发展过程，也是人类认识运动的基本规律。践具有指导作用，认识分为感性认识和理性认识，感性认识要飞跃到理性认识。从这一认识运动过程和基本规律决定了主观和客观、认识和实践的统一是具体的和历史实践到认识，从认识到实践，实践、认的。所谓具体的，即主观认识要同一定时间、地点、条件下的客观实践相符合；所识、再实践、再认识，认识运动不断反复谓历史的，即主观认识要同特定历史发展阶段的客观实践相适应。由于客观实践是具和无限发展，这是人类认识运动的辩证发体的、历史的，所以，主观认识也应是具体的、历史的。当事物的具体过程已经向前展过程，也是人类认识运动的基本规律。推移，转变到另一个具体过程的时候，主观认识就应当随之而转变。如果主观认识仍这一认识运动过程和基本规律决定了主观然停留在原来的阶段上，思想落后于实际，就容易犯保守的错误。当事物的具体过程和客观、认识和实践的统一是具体的和历尚未结束，原有的矛盾尚未得到充分的暴露和展开，向另一个具体过程推移、转变的史的。条件还不具备时，如果人们硬要把将来可能做的事情勉强拿到现在来做，企图超越阶段，就容易犯冒进的错误。所以，“我们的结论是主观和客观、理论和实践、知和行的具体的历史的统一，反对一切离开具体历史的‘左”的或右的错误思想”。马克思主义认识论是党的群众路线工作方法的哲学基础。党的“从群众中来，到群众中去”的工作方法，正是辩证唯物主义和历史唯物主义认识论在实际工作中的创造性运用。群众是实践的主体，也是认识的主体。认识从群众中来，主要是从群众的实践中来；认识回到实践中去，也主要是回到群众的实践中去。",a:"(B)",sol:""},{n:"(18)",q:"【1995.文3】根据认识的发展规律，在认识的“熟知”与“真知”问题上的正确观点是） (A) 熟知即真知 (B) 熟知不等于真知 (C) 熟知起源于真知 (D) 熟知必然转化为真知·055·2024考研政治知识精讲讲义（马原分册）",a:"(B)",sol:""},{n:"(19)",q:"【1995.文5】列宁说，“没有革命的理论，就不会有革命的运动”，这句话应理解为 (A) 革命运动是由革命理论派生的 (B) 革命理论是革命运动的基础 (C) 革命理论对革命实践具有最终的决定作用 (D) 革命理论对革命实践具有重要的指导作用",a:"(D)",sol:""},{n:"(21)",q:"【2016.17】显微摄影是一门使用照相机拍摄显微镜下一般用肉眼无法看清的标本的技术。肉眼中千篇一律的细沙，在显微镜下，却是“一沙一世界”。有的晶莹剔透像宝石，有的金黄酥脆像饼干。即使是司空见惯的柴米油盐，在显微镜下也会展现神奇而充满魅力的另一面。显微镜下的“一沙一世界”表明 (A) 任何事物都具有无限多样的属性djky66 (B) 事物的本质随着人们认识的变化而改变 (C) 人们可以通过制造和使用工具日益深化对客观世界的认识 (D) 人们能够通过对个别事物的认识而达到对世界整体的把握",a:"(ACD)",sol:""},{n:"(25)",q:"【1995.理3】实践高于理论的认识，是因为实践具有 (A) 普遍性 (B) 绝对性 (C) 客观实在性 (D) 直接现实性",a:"(D)",sol:""},{n:"(26)",q:"【1999.文4】一种认识是不是真理，要看它 (A) 能否满足人的需要 (B) 能否被多数人认可 (C) 能否付诸实践 (D) 能否在实践中最终取得预期的效果",a:"(D)",sol:""},{n:"(27)",q:"【2008.3】在听完一位成功的企业家讲课后，一些来自企业的学员感到有些失望，便问他：“你讲的那些内容我们也差不多知道，可为什么我们之间的差距会那么大呢？”这位企业家回答说：“那是因为你们仅是知道，而我却做到了，这就是我们的差别。”这句话表明了实践高于理论认识，因为实践具有 (A) 普遍有效性 (B) 客观规律性 (C) 主体能动性 (D) 直接现实性",a:"(D)",sol:""},{n:"(28)",q:"【2009.2】1978年关于真理标准的大讨论是一场新的思想解放运动。实践之所以成为检验真理的唯一标准，是由(djky66 (A) 真理的主观性和实践的客观性所要求的 (B) 真理的相对性和实践的决定性所预设的 (C) 真理的属性和实践的功能所规定的祝您上岸） (D) 真理的本性和实践的特点所决定的",a:"(D)",sol:""},{n:"(29)",q:"【2020.2】逐渐“飞人寻常百姓家”的人工智能对人类的社会生活产生了巨大影响。对此，技术乐观派认为人工智能为人类发展更新了“发动机”，悲观派则认为人工智能的发展可能导致“人类的终结”。对人工智能社会效用的评价是 (A) 对客观事物发展规律的真理性评价 (B) 对主体需要发展程度的认知性评价微信公众号：djky66 (C) 受主体情感、兴趣和爱好影响的主观性评价 (D) 对客观事物的属性及其满足主体需要的价值性评价（顶尖考研祝您上岸）",a:"(D)",sol:""},{n:"(30)",q:"【2023.18】苏轼在《题西林壁》中写道，“横看成岭侧成峰，远近高低各不同”，人们之所以对同一个事物会有横、侧、远、近、高、低等评价差异，是因为 (A) 评价客体没有自身固有的本质和特性 (B) 评价过程与评价主体有着直接的关系djky66 (C) 评价没有正确与错误、善与恶的区别 (D) 评价结果随主客体的相互关系而变化",a:"(BD)",sol:""},{n:"(31)",q:"【2016.2】有一种观点认为，“自由不在于幻想中摆脱自然规律而独立，而在于认识这些规律，从而能够有计划地使自然规律为一定的目的服务”。还有一种观点认为，“自由’倒过来就是“由自’，因此“自由’等于“由自’，“由自’即是随心所欲”。这两种关于自由的观点( (A) 前者是唯物辩证法的观点，后者是唯意志论的观点 (B) 前者是机械唯物主义的观点，后者是唯心主义的观点 (C) 前者是主观唯心主义的观点，后者是唯物辩证法的观点 (D) 前者是历史唯心主义的观点，后者是历史唯物主义的观点",a:"(A)",sol:"【简析】马克思主义认为自由是对必然的认识和对客观世界的改造。人不能摆脱必然性的制约，只有在认识必然性的基础上才有自由的活动。D正确。"},{n:"(32)",q:"【2009.18】邓小平说：“农村搞家庭联产承包，这个发明权是农民的。农村改革中的好多东西，都是基层创造出来，我们把它拿来加工提高作为全国的指导。”这对我们实现思想理论创新具有普遍指导意义，它要求我们 (A) 要以解放思想为先导 (B) 打破一切理论的约束 (C) 关注生活实践的需要 (D) 尊重人民群众的诉求.069·2024考研政治知识精讲讲义（马原分册）",a:"(ACD)",sol:""}],
  "mayuan_s14": [{n:"(1)",q:"【2023.1】习近平主席在为《复兴文库》所写的序言中指出：“修史立典，存史启智，以文化人是中华民族延续几千年的一个传统，编纂《复兴文库》大型历史文献丛书，重点就是要通过对近代以来重要思想文献的选编，述录先人的开拓，启迪来者的奋斗。历史是最好的教科书，一切向前走，都不能忘记走过的路，走的再远，走到再光辉的未来，也不能忘记走过的过去。“这说明 (A) 历史、现实、未来是相通的 (B) 一切历史都是当代史 (C) 历史过程不包含任何偶然的因素 (D) 历史事件往往可以完整重复和再现0712024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(3)",q:"【2011.2】社会存在是指社会的物质生活条件，它有多方面的内容，其中最能集中体现人类社会物质性的是 (A) 社会形态 (B) 地理环境 (C) 人口因素 (D) 生产方式072",a:"",sol:""},{n:"(4)",q:"【2022.14】法律作为上层建筑的重要组成部分，不是凭空产生的，也不是永恒存在的，是由一定的社会物质生活条件所决定的。决定法律本质、内容和发展方向的根本因素是( (A) 地理环境 (B) 物质资料的生产方式 (C) 人口素质 (D) 统治阶级的意志（二）社会意识社会意识是社会生活的精神方面，是社会存在的反映。社会意识具有复杂的结构，可以从不同角度对其进行划分。根据不同的主体，社会意识分为个体意识和群体意识。个体意识是个人的生活经历和社会地位等在自己头脑中的反映，是个体社会实践的产物；群体意识是群体成员共同的意识，是群体实践的产物。根据不同的层次，社会意识分为社会心理和社会意识形式。社会心理是低层次的社会意识，是自发的、不系统的、不定型的社会意识，表现为人们的感知、情绪、情感、心态、习俗等，以感性认识为主；社会意识形式是高层次的社会意识，是自觉的、系统的、定型的社会意识，包括政治法律思想、道德、艺术、宗教、哲学、科学等，以理性认识为主。社微信公众号：djky66会意识形式以社会心理为基础，并对社会心理起指导和影响作用。在社会意识形式中，又存在意识形态和非意识形态之分，其中意识形态是指反（顶尖考研祝您上岸）映社会的经济关系、阶级关系的社会意识，主要包括政治法律思想、道德、艺术、宗教、哲学等。自然科学和语言学、形式逻辑等一部分社会科学不具有社会经济形态和政治制度的性质，不反映特定社会集团的利益和要求，不服务于特定经济政治制度和特定阶级，因而属于非意识形态政治法律思想包括政治思想和法律思想。政治思想是人们关于政治的关系、制度和设施的观点、理论的总和，法律思想是人们关于法的关系、制度和设施的观点、理论的总和。政治法律思想是随着阶级和国家的出现而产生的，是最直接、最集中地反映经济基础的意识形态，在意识形态中居于核心地位，起主导作用。道德是调整人们之间以及个人与社会之间关系的行为规范的总和，是依靠社会舆论以及人们的信念、习惯、传统和教育来起作用的精神力量。道德是一定生产方式的产物，是对经济基础比较直接的反映。道德具有历史性，不同时代具有不同的道德观念，永恒不变的道德是不存在的。道德具有继承性，一个国家或民族的传统美德在现实生活中具有重要影响和意义。艺术是通过塑造具体生动的形象来反映社会生活的意识形式。它靠形象来表现人们对社会生活的理解、情感、愿望和意志，按照审美的规则来把握和再现生动的社会生活，并通过美的感染力来影响人们的思想情感和社会生活。宗教是支配人们日常生活的外部力量在人们头脑中的虚幻的反映。宗教本质上是一种“颠倒的世界观”，是由对神灵的信仰和崇拜来支配人的思想行为的一种意识形式。从其产生根源看，宗教是自然压迫和社会压迫的产物。在人类社会早期，由于生产力水平极端低下和缺乏科学知识，以及人们对自然现象的无知和恐惧，产生了各种形式的宗教观念。阶级压迫给劳动人民带来苦难，而人们又不能科学地解释这些社会现象，是宗教产生的又一重要根源。宗教最初是被压追者对现实苦难的叹息和抗议，而后被统治阶级所利用，成为其统治被压迫者的思想工具。从历史和现实看，宗教将会长期存在并发挥作用；宗教与一定社会的经济、政治、文化问题交织在一起，对社会发展和稳定产生重大影响，我们必须积极引导宗教与社会主义社会相适应；宗教常常与现实的国际斗争和冲突相交织，是国际关系和世界政治中的一个重要因素，我们必须高度警惕和抵制境外敌对势力利用宗教进行渗透。要努力进行马克思主义宗教观0732024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(5)",q:"【2000.文3】大众心理影响经济走势，能正确解释这一现象的观点是 (A) 社会意识对社会存在具有决定作用 (B) 社会心理可以左右社会发展方向 (C) 只有正确的社会意识才能影响社会发展 (D) 社会意识反作用于社会存在",a:"",sol:""},{n:"(6)",q:"【2007.4】列宁说：“意识到自己的奴隶地位而与之作斗争的奴隶，是革命家。没有意识到自己的奴隶地位而过着默默无言、浑浑噩噩、忍气吞声的奴隶生活的奴隶，是十足的奴隶。对奴隶生活的各种好处津津乐道并对和善的好主人感激不尽以至垂涎欲滴的奴隶是奴才，是无耻之徒。”这三种奴隶的思想意识之所以有如此大的差异，是由于 (A) 人的社会意识并不是社会存在的反映况您上岸） (B) 人的社会意识与社会存在具有不一致性 (C) 人的社会意识中的各种形式之间相互作用 (D) 人的社会意识具有历史继承性",a:"",sol:""},{n:"(7)",q:"【2015.2】社会存在决定社会意识，社会意识是社会存在的反映。社会意识具有相对独立性，即它在反映社会存在的同时，还有自已特有的发展形式和规律。社会意识相对独立性最突出的表现是 (A) 社会意识与社会存在发展的不完全同步性 (B) 社会意识内部各种形式之间的相互作用和影响 (C) 社会意识各种形式各自具有其历史继承性 (D) 社会意识对社会存在具有能动的反作用",a:"",sol:""},{n:"(8)",q:"【2020.19】一方水土孕育一方文化。很早以前，人们就在平原、高原、山地、河谷、海域等广阔的地理空间发展出农耕、渔猎、游牧等不同经济形态，进而形成具有明显地域差别的文化。高铁、互联网等虽然极大消除了不同地域空间之间的界限，加速地域文化的同质性转化，但地域文化并没有消失，还在持续对当代社会发展产生重要影响。“一方水土孕育一方文化”表明 (A) 社会经济状况决定文化发展形态 (B) 自然地理空间影响文化的外在特征 (C) 文化是人类社会发展的决定力量 (D) 不同形态文化的发展具有相对独立性0752024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(9)",q:"【2021.3】智能生物识别等人工智能新技术快速走进老百姓的生活。然而，在新技术快速发展应用的同时，也因法律法规相对滞后而引发人们对信息安全和隐私保护的担忧。有专家呼吁，在发展新技术时，要划定法律禁区，制定行业规范，构建一个新技术健康发展的法律法规体系。从社会意识和社会存在的关系看，法律法规 (A) 与新技术发展具有不平衡性 (B) 总是阻碍新技术的健康发展 (C) 只能落后于新技术发展 (D) 归根到底是新技术发展的内在动力不暇接，了解这些网络语的意思用法，几乎成了网上冲浪的必修课。嵌入日常生活交流的网络热词，为语言的发展带来新语料，也能够让人们一窥当下的社会生活和社会心态。网络热词流行的现象表明",a:"",sol:""},{n:"(11)",q:"【2002.文2】先进生产力的集中体现和主要标志是 (A) 劳动者 (B) 劳动对象 (C) 科学技术 (D) 管理方式",a:"",sol:""},{n:"(12)",q:"【2002.文5】社会生产过程中起决定性作用的环节是 (A) 交换 (B) 生产 (C) 消费 (D) 分配",a:"(B)",sol:""},{n:"(13)",q:"【1996.理2】衡量生产力水平的客观尺度是 (A) 劳动工具的状况 (B) 劳动者的素质 (C) 劳动对象的广度和深度 (D) 劳动产品的数量和质量",a:"(A)",sol:""},{n:"(15)",q:"【1991.文10】上层建筑对社会发展作用的性质取决于 (A) 国家政权的阶级属性 (B) 社会生产力的发展水平 (C) 它所服务的经济基础的性质 (D) 社会意识的性质和发展水平",a:"(C)",sol:""},{n:"(16)",q:"【1994.文2】在社会生活中，上层建筑对于社会发展作用的性质取决于（ (A) 国家政权的阶级属性 (B) 它所服务的经济基础的性质 (C) 社会意识形态的性质 (D) 社会生产力的性质·081.2024考研政治知识精讲讲义（马原分册）",a:"(B)",sol:""},{n:"(18)",q:"【2012.18】2011年4月，耶鲁大学出版了《马克思为什么是对的》一书，书中列举了当前西方社会10个典型的歪曲马克思主义的观点。其中一种观点认为：马克思主义将世间万物都归结于经济因素，艺术、宗教、政治、法律、道德等都被简单地视为经济的反映，对人类历史错综复杂的本质视而不见，而试图建立一种非黑即白的单一历史观。上述观点是对马克思主义关于经济基础和上层建筑辩证关系思想的严重歪曲，其表现为 (A) 把社会历史发展多重因素的综合作用歪曲为单一因素决定论 (B) 把上层建筑与经济基础的相互作用歪曲为机械的单向作用 (C) 把经济作为社会的“基础”所具有的归根到底的决定作用歪曲为唯一决定作用 (D) 把意识形态对社会历史始终具有的积极能动作用歪曲为消极被动作用",a:"(ABC)",sol:""},{n:"(19)",q:"【2009.3】近年来，马克思的《资本论》在西方一些国家销量大增。列宁曾说，马克思的《资本论》的成就之所以如此之大，是由于这本书使读者看到整个资本主义社会形态是个活生生的形态，既有“骨骼”，又有“血肉”。人类社会作为一种活的有机体，其“骨骼”系统是指 (A) 地理环境、人口因素和生产方式等社会物质生活条件 (B) 与一定的生产力相适应的生产关系微信公众号：djky66 (C) 建立在一定经济基础之上的政治法律制度及设施 (D) 由政治法律思想、道德、宗教、哲学等构成的社会意识形态（顶尖考研祝您上岸）",a:"(B)",sol:""},{n:"(20)",q:"【2023.2】社会形态是关于社会运动的具体形式，发展阶段和不同质态的范畴，是同生产力发展一定阶段相适应的经济基础和上层建筑的统一体。人类历史社会划分为原始社会、奴隶社会、封建社会、资本主义社会和共产主义社会（社会主义社会是其第一阶段）五种社会形态，其依据是 (A) 生产工具的质量和数量 (B) 统治集团的阶级和政治属性 (C) 经济基础特别是生产关系的性质 (D) 人们社会交往和分工的范围和水平",a:"(C)",sol:""},{n:"(25)",q:"【2019.3】马克思指出，判断一个变革时代不能以该时代的意识为依据，相反，这个意识必须从物质生活的矛盾中去解释。这里的“物质生活的矛盾”从根本上说是( (A) 社会生产力和生产关系的现存冲突djky66 (B) 经济基础与上层建筑的现存冲突微你上岸） (C) 人类社会与自然界的现存冲突 (D) 社会存在与社会意识的现存冲突",a:"",sol:""},{n:"(26)",q:"【1996.文3】阶级产生的直接原因是 (A) 一部分人对另一部分人的暴力掠夺 (B) 社会产品的分配不均 (C) 剩余产品的出现 (D) 生产资料私有制的形成",a:"",sol:""},{n:"(28)",q:"【1997.理5】社会主义国家的改革，其性质应该是 (A) 社会主义基本制度的变革 (B) 社会主义经济运行方式的改变 (C) 社会主义体制的修补 (D) 社会主义制度的自我完善和发展",a:"",sol:""},{n:"(29)",q:"【2009.19】“随着新生产力的获得……人们也就会改变自己的一切社会关系。手推磨产生的是封建主义的社会，蒸汽磨产生的是工业资本家的社会。”这段话表明科学技术是( (A) 历史上起推动作用的革命力量 (B) 历史变革中的唯一决定性力量 (C) 推动生产方式变革的重要力量 (D) 一切社会变革中的自主性力量",a:"",sol:""},{n:"(30)",q:"【2010.181历史经验表明，经济危机往往孕育着新的科技革命。1857年的世界经济危机引发了电气革命，推动人类社会从蒸汽时代进人电气时代。1929年的世界经济危机引发了电子革命，推动人类社会从电气时代进人电子时代。由此证明djky66 (A) 科技革命是摆脱社会危机的根本出路 (B) 科学技术是社会形态更替的根本标志您上岸） (C) 社会实践的需要是科技发展的强大动力 (D) 科技创新能够推动社会经济跨越式发展",a:"",sol:""},{n:"(31)",q:"【2019.18】基因编辑是应对遗传性疾病的一种潜在治疗办法，但其技术运用极具争议，这不仅是因为基因的变化会传给后代并最终有可能影响整个基因库，而且更重要的是基因编辑会产生长远而深刻的社会影响，可能衍生出一系列棘手的伦理、法律和安全难题。正因为如此，许多国家对人类基因编辑技术制定了相应的伦理、法律规范。人类严格控制基因编辑行为的原因在于( (A) 人的实践活动要遵循真理尺度与价值尺度的统一 (B) 基因编辑技术可能突破人类的伦理道德底线 (C) 科学技术有时表现为异已的、敌对的力量 (D) 人的实践活动是合规律性与合目的性的统一",a:"",sol:""},{n:"(32)",q:"【1997.文21马克思主义揭示人的本质的出发点是 (A) 人的自身需要 (B) 人类的共同利益 (C) 人的自然属性 (D) 人的社会关系",a:"",sol:""},{n:"(33)",q:"【2009.4】卢梭在《论人类不平等的起源和基础》中说道：“我认为，在人类的一切知识中，最有用但也最不完善的知识就是关于人的知识。”马克思的唯物史观破解了人是什么这一“司芬克斯之谜”。马克思在《关于费尔巴哈的提纲》中指出，人的本质在其现实性上是 (A) 自然属性和社会属性的内在统一微信公众号：djky66 (B) 所有人共同属性的概括（顶尖考研祝您上岸） (C) 一切社会关系的总和 (D) 自由理性的外化",a:"",sol:""},{n:"(35)",q:"【2013.18】唯物史观第一次科学地解决了历史创造者的问题，认为人民群众是历史的创造者。人民群众 (A) 从量上说是指社会人口的绝大多数 (B) 从质上说是指一切对社会历史发展起推动作用的人们 (C) 在任何历史时期都不包括剥削阶级 (D) 最稳定的主体部分始终是从事物质资料生产的劳动群众及其知识分子096·",a:"",sol:""},{n:"(36)",q:"【2018.3】坚持以人民为中心，就必须坚持人民主体地位，坚持立党为公、执政为民，践行全心全意为人民服务的根本宗旨，把党的群众路线贯彻到治国理政全部活动之中，把人民对美好生活的向往作为奋斗目标。“坚持以人民为中心”的理论基础是唯物史观关于( (A) 人民群众是历史的创造者的原理 (B) 人的本质是一切社会关系的总和的原理 (C) 人民群众的活动受到社会历史条件制约的原理 (D) 总体的人在总体的历史过程中的主体地位的原理",a:"",sol:""},{n:"(37)",q:"【2008.19】马克思主义哲学中的辩证法、认识论、历史观在本质上是一致的，体现这种一致性的公式有 (A) 个别—一般—个别 (B) 实践—认识一实践 (C) 群众一领导一群众 (D) 团结—批评—团结",a:"",sol:""},{n:"(38)",q:"【2023.17】马克思、恩格斯在领导无产阶级斗争的实践中，始终强调领袖权威的必要性和重要性。马克思说过，一个单独的提琴手自己指挥自己，一个乐队就需要一个乐队指挥。恩格斯也指出，“没权威就不可能有任何的一致行动”，并以大海航行的例子说明权威的重要性。在总结巴黎公社失败的经验教训时，马克思深刻指出，革命胜利后组织新政权、维护新政权、建设新政权都需要权威。恩格斯则明确指出，巴黎公社遭到灭亡，就是由于缺乏集中和权威。这表明，无产阶级领导在历史上可以（ (A) 引领社会发展的方向 (B) 影响历史事件的进程 (C) 凝聚人民群众的力量 (D) 创建人类社会的历史",a:"",sol:""},{n:"(40)",q:"【2014.18】作家史铁生在《奶奶的星星》中讲道，奶奶告诉他的故事与通常的说法不同：一般人说，地上死一个人，天上就熄灭一颗星星；而奶奶说，地上死一个人，天上又多了一个星星，人死了就会升到天空，变成星星给走夜道的人照个亮了。于是他“慢慢相信，每一个活过的人，都能给后人的路途上添些光亮，也许是一颗巨星，也许是一把火炬，也许只是一支含泪的烛光….”这对我们理解个人在社会历史中的作用的启示有(） (A) 杰出个人决定历史发展的走向 (B) 人人都是历史的创造者微信公众号：djky66 (C) 历史是无数个人相互作用的合力的结果 (D) 每个人对社会发展都有或大或小的作用（顶尖考研祝您上岸）",a:"(CD)",sol:""},{n:"(41)",q:"【2015.19】马克思主义从必然性和偶然性的辩证统一中理解杰出人物的历史作用，认为 (A) 杰出人物会因其智慧、性格因素对社会进程发生影响 (B) 杰出人物的历史作用受到一定历史条件的制约 (C) 杰出人物能够改变历史发展的基本方向 (D) 杰出人物历史作用的形成和发挥与其顺应人民群众的意愿密不可分",a:"(ABD)",sol:""},{n:"(42)",q:"【2017.18】唯物史观在坚持人民群众是历史的创造者这一基本前提下，高度重视个人在历史上的作用。历史人物是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物。下列关于历史人物历史作用的正确认识是（） (A) 历史人物不论发挥什么样的作用都不能决定和改变历史发展的总进程和总方向 (B) 历史人物会因其智慧、性格等因素对社会进程发生影响 (C) 具有进步意义的历史人物往往能够首先发现或提出历史进程中新的历史任务 (D) 历史人物对历史发展的作用都是积极的",a:"(ABC)",sol:""},{n:"(43)",q:"【2018.18】社会形态的更替具有客观性和必然性，但这并不否定人们历史活动的能动性，并不排斥人们在遵循社会发展规律的基础上，对于某种社会形态的历史选择性。人们历史活动的能动性和选择性主要体现在 (A) 社会发展的客观必然性为人们的历史选择提供了基础、范围和可能性空间 (B) 社会形态更替的过程是主体能动性与客观规律性相统一的过程 (C) 人们的历史选择性归根结底是人民群众的选择性 (D) 社会发展的客观过程由每一个参与历史活动的个人的主观意志所决定·101·2024考研政治知识精讲讲义（马原分册）",a:"(ABC)",sol:""}],
  "mayuan_s18": [{n:"(1)",q:"【2021.19】商品经济是一定社会历史条件的产物。商品经济得以产生的社会历史条件有 (A) 生产资料和劳动产品属于不同的所有者 (B) 社会分工的出现及其存在 (C) 商品具有了使用价值与价值两个因素 (D) 交换过程中形成了充当一般等价物的商品",a:"(AB)",sol:""},{n:"(2)",q:"【1996.理31作为商品的计算机软件，其价值的物质承担者是 (A) 软件磁盘本身 (B) 软件的有用性 (C) 购买软件的货币 (D) 应用软件的计算机价值是凝结在商品中的无差别的一般人类劳动，即人的脑力和体力的耗费。价值是商品所特有的社会属性，是商品的本质属性。任何有用物品都具有使用价值，但只有这种有用物品是劳动产品并作为商品时才具有价值。使用价值不同的商品之所以能按一定比例相互交换，就是因为它们都具有价值。商品的价值在质上是相同的，因而可以相互比较。商品的价值是劳动创造的，其实质是凝结在商品中的无差别的一般人类劳动，商品交换实际上是商品生产者之间相互交换劳动的关系，商品的价值在本质上体现了生产者之间一定的社会关系交换价值首先表现为一种使用价值同另一种使用价值相交换的量的关系或比例决定商品交换的比例的不是商品的使用价值，而是价值。价值是交换价值的基础，交换价值是价值的表现形式商品的使用价值和价值之间是对立统一的关系。其对立性表现在：商品的使用价值和价值是相互排斥的，二者不可兼得。要想获得商品的价值，就必须放弃商品的使石磊老师提示用价值；要想获得商品的使用价值，就不能获得商品的价值。商品生产者生产商品并不是为了获得使用价值，而是为了获得价值，只是为了获得价值，才关心使用价值。价值是商品的本质因素。使用价值是交换价值的物质承担者。商品生产者只有将商品的使用价值让渡给商品购买者，才能获得价值。其统一性表现商品的使用价值和价值二者不可兼得。在：作为商品，必须同时具有使用价值和价值两个因素。使用价值是价值的物质承担价值决定交换价值、交换价值表现着者，价值寓于使用价值之中。一种物品如果没有使用价值，就是无用之物，即使人们价值。为它付出了大量的劳动，也没有价值。反之，一种物品尽管具有使用价值，但如果不是劳动产品，也没有价值。",a:"(B)",sol:""},{n:"(3)",q:"【1995.文4】马克思指出：“如果物没有用，那么其中包含的劳动也就没有用，不能算作劳动，因此不形成价值。”这段话说明 (A) 价值的存在以物的有用性为前提 (B) 价值的存在与物的有用性互为前提 (C) 只要物是有用的，它就有价值 (D) 物越是有用就越有价值",a:"(A)",sol:"【简析】作为商品，必须同时具有使用价值和价值。有价值的一定有使用价值（商品的价值以使用价值为前提），而有使用价值的不一定有价值。A正确，B、C、D错误。"},{n:"(4)",q:"【2000.文、理4】马克思在研究商品时，之所以考察商品的使用价值，因为使用价值是 (A) 构成财富的物质内容 (B) 人类生存、发展的物质条件 (C) 满足人们需要的物质实体 (D) 商品交换价值的物质承担者·104",a:"(D)",sol:""},{n:"(5)",q:"【2013.3】《资本论》中有这样的表述：“对上衣来说，无论是裁缝自已穿还是他的顾客穿，都是一样的。”这主要是因为无论谁穿 (A) 上衣都起着使用价值的作用 (B) 上衣都起着价值的作用 (C) 上衣都是抽象劳动的结果 (D) 上衣都是社会劳动的结果（二）生产商品的劳动的二重性商品是劳动产品，生产商品的劳动可区分为具体劳动和抽象劳动。具体劳动是指生产一定使用价值的具体形式的劳动。抽象劳动是指撇开一切具体形式的、无差别的一般人类劳动，即人的脑力和体力的耗费。生产商品的具体劳动创造商品的使用价微信公众号：djky66值，抽象劳动形成商品的价值。具体劳动和抽象劳动是同一劳动的两种规定。任何一（顶尖考研祝您上岸）种劳动，一方面是特殊的具体劳动，另一方面又是一般的抽象劳动，这就是劳动的二重性。正是劳动的二重性决定了商品的二因素。劳动二重性学说是理解马克思政治经济学的枢纽具体劳动和抽象劳动是对立统一的关系。一方面，具体劳动和抽象劳动不是各自独立存在的两种劳动或两次劳动，它们在时间上和空间上是统一的，是商品生产者的石磊老师提示同一劳动过程不可分割的两个方面。另一方面，具体劳动与抽象劳动又分别反映劳动具体劳动和抽象劳动不是两种劳动、两个的不同属性，具体劳动所反映的是人与自然的关系，是劳动的自然属性；而抽象劳动劳动，而是同一劳动的两种规定。所反映的是商品生产者的社会关系，是劳动的社会属性。djky66",a:"(A)",sol:""},{n:"(6)",q:"【2002.理4】理解马克思政治经济学的枢纽是岸 (A) 剩余价值学说考研 (B) 生产价格理论 (C) 劳动二重性学说 (D) 劳动力商品理论",a:"(C)",sol:""},{n:"(7)",q:"【2018.4】《资本论》（德文版）第一卷于1867年9月在汉堡出版，其影响力历经150年风雨而不衰，至今对我们分析、理解现实经济问题依然具有很强的指导意义。马克思主义政治经济学的理论十分丰富，其中“理解政治经济学的枢纽”的理论是 (A) 商品二因素理论 (B) 价值规律理论 (C) 劳动二重性理论 (D) 剩余价值理论",a:"(C)",sol:""},{n:"(8)",q:"【1995.理4】商品的价值量由生产商品的社会必要劳动时间决定，它是在（ (A) 同类商品的生产者之间的竞争中实现的 (B) 不同商品生产者之间的竞争中实现的 (C) 商品的生产者和消费者之间的竞争中实现的 (D) 商品的生产者和销售者之间的竞争中实现的生产商品所需要的社会必要劳动时间随着劳动生产率的变化而变化。劳动生产率水平越高，单位时间内生产的商品数量越多，生产每件商品所需要的社会必要劳动时间就越少，单位商品的价值量就越小，反之就越大。商品的价值量与生产商品所耗费的劳动时间成正比，与劳动生产率成反比。劳动生产率指的是劳动者生产使用价值的石磊老师提示效率。它的高低可以用单位劳动时间内生产的商品数量来测量，也可以用单位商品中同一劳动时间内，如果劳动生产率提高，所耗费的劳动时间来测量。影响劳动生产率的因素很多，主要有劳动者的平均熟练程在单位劳动时间内生产的商品数量增加、度、科学技术的发展程度及其在生产中的应用、生产过程的社会结合、生产资料的规使用价值数量增加，单位商品的价值量减模和效能以及自然条件等。少，总价值量不变。",a:"(A)",sol:""},{n:"(9)",q:"【1994.理4】投入某种物质商品生产过程中的活劳动量不变，如果劳动生产率提高，在单位劳动时间内生产的商品数量和单位商品的价值量之间，两者的变化表现为() (A) 商品数量增加，价值量不变 (B) 商品数量不变，价值量增大 (C) 商品数量增加，价值量减少 (D) 商品数量增加，价值量增大",a:"(C)",sol:""},{n:"(10)",q:"【2008.21】同一劳动在同一时间内，当部门劳动生产率提高时会使 (A) 单位商品的价值量降低 (B) 商品的使用价值量增加开祝 (C) 单位商品的价值量不变 (D) 单位商品的价值量提高开",a:"(AB)",sol:"【简析】同一劳动在同一时间内，当部门劳动生产率提高时，生产商品的社会必要劳动时间缩短，单位商品的价值量降低，商品的数量即使用价值量增加，商品的价值总量不变。A、B正确，C、D错误。"},{n:"(11)",q:"【2023.3】马克思在《资本论》中指出：“不管生产力发生了什么变化。同一劳动在同样的时间内提供的价值量总是相同的。但它在同样的时间内提供的使用价值量是不同的，生产力提高时就多些，生产力降低时就少些。”这句话表明，生产力的变化C (A) 不影响同一劳动在同样的时间内生产的商品数量 (B) 不改变同一劳动在同样的时间内的生产效率 (C) 影响同一劳动在同样的时间内生产的单个商品价值量 (D) 改变同一劳动在同样的时间内提供的价值总量商品的价值量同简单劳动与复杂劳动有密切的关系。简单劳动是指不需要经过专门训练和培养的一般劳动者都能从事的劳动。复杂劳动是指需要经过专门训练和培养，具有一定文化知识和技术专长的劳动者所从事的劳动。形成商品价值量的劳动是以简单劳动为尺度的。复杂劳动等于自乘的或多倍的简单劳动，也就是说，少量的复杂劳动等于多倍的简单劳动。在相同的劳动时间里，复杂劳动创造的价值大于简单劳动创造的价值。在以私有制为基础的商品经济条件下，复杂劳动转化为简单劳动，不是商品生产者自觉计算出来的，而是在商品交换过程中自发实现的",a:"(C)",sol:"【简析】提高劳动生产率会使单位时间内生产的商品数量增加，个别商品的价值量减少，但单位时间内生产的总价值量不变。D正确。"},{n:"(12)",q:"【2020.3】在相同的劳动时间里，复杂劳动创造的价值大于简单劳动创造的价值。在以私有制为基础的商品经济条件下，复杂劳动转化为简单劳动 (A) 是商品生产者自觉计算出来的 (B) 是市场管理部门事先规定的 (C) 是商品生产者协商出来的 (D) 是商品交换过程中市场机制自发实现的·106·",a:"(D)",sol:""},{n:"(13)",q:"【2007.5】货币的本质是 (A) 商品交换的媒介物 (B) 商品价值的一般等价物 (C) 商品的等价物 (D) 商品相对价值形式石老师提示",a:"(B)",sol:""},{n:"(15)",q:"【1996.文4】在下列经济行为中，属于货币执行流通手段职能的是 (A) 顾客用10元钱可购买5斤苹果 (B) 顾客购买5斤苹果，一周后付款10元 (C) 顾客用10元钱购买了5斤苹果 (D) 顾客向水果店以每斤2元的价格预定5斤苹果",a:"(C)",sol:"【简析】货币执行支付手段职能是指货币在清偿债务或延期支付时执行的职能。B、C正确。A是执行价值尺度职能；D是执行流通手段职能。"},{n:"(16)",q:"【1999.理5】货币能够执行价值尺度的职能，因为货币 (A) 有特殊的使用价值 (B) 是商品交换的媒介 (C) 自身也有价值 (D) 可作为支付手段·1072024考研政治知识精讲讲义（马原分册）",a:"(C)",sol:""},{n:"(18)",q:"【2005.5】在市场上，一台笔记本电脑的标价是12000元，那么此时执行价值尺度职能的货币是 (A) 实在的货币 (B) 信用货币 (C) 观念上的货币 (D) 现金",a:"(C)",sol:""},{n:"(19)",q:"【2014.19】1918年，马寅初在一次演讲时，有一位老农问他：“马教授，请问什么是经济学？”马寅初笑着说：“我给这位朋友讲个故事吧：有个赶考的书生到旅店投宿，拿出十两银子，挑了该旅店标价十两银子的最好房间，店主立刻用它到隔壁的米店付了欠单，米店老板转身去屠夫处还了肉钱，屠夫马上去付清了欠的饲料款，饲料商赶紧到旅店还了房钱。就这样，十两银子又到了店主的手里。这时书生来说，房间不合适，要回银子就走了。你看，店主一文钱也没赚到，大家却把债务都还清了，所以，钱的流通越快越好，这就是经济学。”在这个故事中，货币所发挥的职能有 (A) 流通手段尖考研祝 (B) 价值尺度 (C) 支付手段 (D) 贮藏手段",a:"(ABC)",sol:""},{n:"(20)",q:"【2022.3】马克思在《资本论》中指出：“一个商品占有者出售他现有的商品，而另一个商品占有者却只是作为货币的代表或作为未来货币的代表来购买这种商品。卖者成为债权人，买者成为债务人。由于商品的形态变化或商品的价值形式的发展在这里起了变化，货币也就取得了另一种职能。”这里所论述的货币“另一种职能”指的是 (A) 价值尺度 (B) 支付手段 (C) 贮藏手段 (D) 流通手段",a:"(B)",sol:""},{n:"(24)",q:"【2002.文4】个别劳动的社会性质，通过 (A) 商品有用性来体现 (B) 商品广告传播来实现 (C) 商品的交换来体现 (D) 商品质量鉴定来体现私人劳动和社会劳动的矛盾构成私有制商品经济的基本矛盾，这一矛盾贯穿商品经济发展过程的始终，决定着商品经济的各种内在矛盾及其发展趋势首先，私人劳动和社会劳动的矛盾决定着商品经济的本质及发展过程。商品经济是以交换为目的的经济形式，交换体现了商品经济的本质。商品经济的交换本质正是由私人劳动和社会劳动的矛盾决定的。在商品经济条件下，每个生产者的劳动本身微信公众号：djky66是私人劳动，而私人劳动要转化为社会劳动，就必须用自已的产品去同别人的产品交（顶尖考研祝您上岸）换。在这里，交换是解决私人劳动和社会劳动之间矛盾的唯一途径。其次，私人劳动和社会劳动的矛盾是商品经济其他一切矛盾的基础。在私有制商品经济条件下，商品的使用价值和价值之间的矛盾是由生产商品的具体劳动和抽象劳动之间的矛盾决定的。在商品交换过程中，生产商品使用价值的具体劳动是不能直接进行量的比较的，只有将具体劳动还原为抽象劳动，也就是从具体劳动中抽象出无差石磊老师提示别的一般人类劳动，才能进行量的比较。具体劳动能否还原为抽象劳动，在根本上取注意：简单商品经济的各种矛盾，也就是决于私人劳动和社会劳动能否实现统一。商品生产者的私人劳动生产的产品如果与社商品的内在矛盾，即使用价值和价值的矛会的需求不相适应，这种私人劳动就不会被承认为社会劳动，它作为具体劳动的有用盾；具体劳动和抽象劳动的矛盾；私人劳性质也就不会为社会所承认，因而不能还原为抽象劳动，这意味着商品的价值不能实动和社会劳动的矛盾；私人劳动时间与社会劳动时间的矛盾（注：某一对矛盾的内现，商品的使用价值和价值之间的矛盾没有得到解决。反过来，如果私人劳动生产的在表现形式是其余三对）。产品为社会所接受，则这种私人劳动就会被承认并转化为社会劳动，它作为具体劳动的有用性质就会为社会所承认，因而可以还原为抽象劳动，这意味着商品的价值得到了实现，商品的使用价值和价值之间的矛盾得到了解决。最后，私人劳动和社会劳动的矛盾决定着商品生产者的命运。商品的售卖过程是私人劳动转化为社会劳动的过程，这个过程进行得是否顺利，决定着生产者的经济利益甚至命运。商品生产者生产的商品只有卖出去，其耗费的劳动才能得到补偿，生产者才能生存和进行再生产。如果商品卖不出去，生产者的劳动耗费得不到补偿，再生产就难以进行。在私有制商品经济条件下，私人劳动与社会劳动之间的矛盾通过商品的运动、价值的运动、货币的运动决定商品生产者的命运，这使商品生产者认为商品、价值乃至货币似乎是物的自然属性，而这种所谓的自然属性又似乎具有一种超自然的神秘性，商品生产者不能自己掌握自己的命运，而是听凭商品、价值、货币运动的摆布，人们之间一定的社会关系在人们面前采取了物与物的关系的虚幻形式，马克思称之为商品拜物教。私有制商品经济条件下商品世界的拜物教性质的产生具有必然性：其一，私有制商品经济条件下劳动产品只有采取商品的形式才能进行交换，人类劳动的等同性只有采取同质的价值形式才能在交换中体现出来。其二，劳动量只有采取价值量这一物的形式才能进行计算和比较。其三，生产者的劳动关系的社会性质只有采取商品之间即物与物之间相交换的形式才能间接地表现出来，这就使人们之间一定的社会关系被物与物的关系所掩盖，具有了拜物教性质。商品世界的拜物教性质，或者生产商品的劳动的社会性质所具有的物的外观掩盖了商品经济关系的本质，妨碍人们透过物的外表认识商品、价值以及货币的实质。在私有制商品经济条件下，私人劳动和社会劳动之间的矛盾是私有制商品经济的基本矛盾。在资本主义制度下，这种矛盾进一步发展成资本主义的基本矛盾，即生产1112024考研政治知识精讲讲义（马原分册）",a:"(C)",sol:""},{n:"(25)",q:"【2011.3】马克思把商品转换成货币称为“商品的惊险的跳跃”，“这个跳跃如果不成功，摔坏的不是商品，但一定是商品占有者”。这是因为只有商品变为货币 (A) 货币才能转化为资本 (B) 价值才能转化为使用价值 (C) 抽象劳动才能转化为具体劳动 (D) 私人劳动才能转化为社会劳动",a:"(D)",sol:""},{n:"(26)",q:"【2019.4】在以私有制为基础的商品经济中，商品生产者的私人劳动生产的产品是否与社会的需求相适应，作为具体劳动的有用性质能否为社会所承认，商品的使用价值和价值之间的矛盾是否能得到解决，决定着商品生产者的命运。以私有制为基础的商品经济的基本矛盾是 (A) 使用价值和价值之间的矛盾 (B) 私人劳动和社会劳动之问的矛盾 (C) 具体劳动和抽象劳动的矛盾 (D) 脑力劳动和体力劳动的矛盾",a:"(B)",sol:""},{n:"(28)",q:"【2012.19】人们往往将汉语中的“价”“值”二字与金银财宝等联系起来，而这两字的偏旁却都是“人”，示意价值在“人”。马克思劳动价值论透过商品交换的物与物的关系，揭示了商品价值的科学内涵，其主要观点有( (A) 劳动是社会财富的唯一源泉 (B) 具体劳动是商品价值的实体 (C) 价值是凝结在商品中的一般人类劳动 (D) 价值在本质上体现了生产者之间的社会关系",a:"(CD)",sol:""},{n:"(29)",q:"【2017.19】马克思指出，所谓资本原始积累“只不过是生产者和生产资料分离的历史过程。这个过程所以表现为“原始的”，因为它形成资本及与之相适应的生产方式的前史”。资本原始积累的主要途径有 (A) 用资本手段获取市场暴利 (B) 用剥削手段榨取剩余价值 (C) 用野蛮手段进行殖民掠夺 (D) 用暴力手段剥夺农民土地",a:"(CD)",sol:""},{n:"(30)",q:"【1994.理3】在商品生产过程中，生产资料的价值是借助于生产者的 (A) 具体劳动而增殖 (B) 具体劳动转移到新产品中 (C) 抽象劳动而增殖 (D) 抽象劳动转移到新产品中劳动力是指人的劳动能力，是人的脑力和体力的总和。劳动力的使用即劳动。人的劳动是任何社会进行生产都不可缺少的基本条件、基本要素，没有劳动就不可能有人类社会的生存与发展。劳动力成为商品，要具备两个基本条件：其一，劳动者是自由人，能够把自己的劳动力当作自已的商品来支配；其二，劳动者没有别的商品可以出卖，自由得一无所有，没有任何实现自已的劳动力所必需的物质条件。劳动力成为商品的两个条件并不是自古以来就有的，而是在封建社会后期发生的资本原始积累过程中逐渐形成的。劳·115·2024考研政治知识精讲讲义（马原分册）",a:"(B)",sol:"【简析】具体劳动转移生产资料的价值到新产品中去；抽象劳动形成商品的价值，并把劳动力商品的价值再生产（再创造）出来。D正确。"},{n:"(31)",q:"【2009.22】劳动力是任何社会生产的基本要素，在特定的社会发展阶段和特定的历史条件下，劳动力作为一种特殊商品，其价值的构成包括 (A) 维持劳动者自身生存所必需的生活资料的价值 (B) 劳动者在必要时间内创造的价值 (C) 劳动者繁育后代所必需的生活资料的价值 (D) 培养和训练劳动者所需要的费用",a:"(ACD)",sol:""},{n:"(32)",q:"【2010.4】劳动力成为商品是货币转化为资本的前提条件，这是因为 (A) 资本家购买的是劳动力的价值 (B) 劳动力商品具有价值和使用价值 (C) 货币所有者购买的劳动力能够带来剩余价值 (D) 劳动力自身的价值能够在消费过程中转移到新的商品中去116·",a:"(C)",sol:""},{n:"(33)",q:"【2001.文3，理51资本主义再生产过程的实质是 (A) 劳动过程和价值形成过程的统一 (B) 劳动过程和价值增殖过程的统一 (C) 物质资料再生产与资本主义生产关系再生产的统一 (D) 物质资料再生产与劳动力再生产的统一",a:"(C)",sol:""},{n:"(34)",q:"【2013.191美国导演迈克尔·穆尔的最新纪录片《资本主义：一个爱情故事》问世以来，一直颇受关注。“资本主义”为何与“爱情故事”联系起来？穆尔解释说，这是一种“贪欲之爱”，“喜爱财富的人不仅爱他们自己的钱，也爱你口袋中的钱….·很多人不敢说出它的名字，真见鬼，就说出来吧，这就是资本主义。”对金钱的“贪欲”之所以与资本主义连为一体，是因为 (A) 资本家是人格化的资本 (B) 赚钱体现了人的天然本性 (C) 资本的生命在于不断运动和不断增殖 (D) 追逐剩余价值是资本主义生产方式的绝对规律在价值增殖过程中，雇佣工人的劳动分为两部分：一部分是必要劳动，用于再生产劳动力的价值；另一部分是剩余劳动，用于无偿地为资本家生产剩余价值。工人的全部劳动时间分为必要劳动时间和剩余劳动时间两部分。所谓必要劳动时间，是指工人再生产劳动力价值的时间；所谓剩余劳动时间，是指工人无偿地为资本家生产剩余价值的时间。工人的剩余劳动，乃是剩余价值的源泉",a:"(ACD)",sol:""},{n:"(35)",q:"【2008.5】马克思通过对资本主义生产中价值增殖过程的分析，雇佣工人的劳动时间分为 (A) 生产使用价值的时间和生产价值的时间 (B) 转移旧价值的时间和创造新价值的时间 (C) 生产生产资料价值的时间和生产剩余价值的时间 (D) 再生产劳动力价值的时间和生产剩余价值的时间剩余价值就是由雇佣工人创造的、被资本家无偿占有的、超过劳动力价值以上的那部分价值。它是雇佣工人剩余劳动的凝结，体现了资本家与雇佣工人之间剥削与被剥削的关系118",a:"(D)",sol:""},{n:"(36)",q:"【2013.4】某资本家投资100万元，每次投资所获得的利润是15万元，假定其预付资本的有机构成为4：1，那么该资本家每次投资所实现的剩余价值率为（ (A) 50% (B) 75% (C) 100% (D) 125%",a:"(B)",sol:"【简析】c+v=100万元，c∶v=3∶1，则c=75万元，v=25万元。m/v=200%，则m=50万元。利润与剩余价值在量上是一样的，故利润为50万元。C正确。"},{n:"(37)",q:"【2016.31某资本家投资100万元创办企业从事生产，60万元用于固定资本，以购买机器设备等，40万元用于流动资本，以购买原材料和劳动力等（其中购买劳动力支付了10万元）。一轮生产结束后，该企业的总资本达到了120万元。那么，该企业的剩余价值率为 (A) 20% (B) 50% (C) 100% (D) 200%",a:"(D)",sol:""},{n:"(38)",q:"【1991.11】资本家竞相改进技术的直接动因是 (A) 降低劳动力价值 (B) 追逐超额剩余价值 (C) 获取绝对剩余价值 (D) 获取相对剩余价值",a:"(B)",sol:""},{n:"(39)",q:"【1999.文5】某资本家经营的企业通过改进技术、提高劳动生产率，使其生产商品花费的时间比社会必要劳动时间少10%，由此形成商品个别价值低于社会价值的那部分是 (A) 超额剩余价值 (B) 绝对剩余价值 (C) 相对剩余价值 (D) 剩余价值",a:"(A)",sol:"【简析】超额剩余价值是指企业由于提高劳动生产率而使商品的个别价值低于社会价值的差额。A正确。"},{n:"(40)",q:"【2002.文6】资本家普遍获得相对剩余价值是 (A) 单个资本家采用先进技术降低商品个别价值的结果 (B) 单个资本家压低劳动力价值缩短工人必要劳动时间的结果 (C) 资本家延长工人劳动时间增加工人剩余劳动时间的结果 (D) 各个资本家追求超额剩余价值的结果120",a:"(D)",sol:""},{n:"(41)",q:"【2015.3】第二次世界大战以后，资本主义国家经历了第三次科技革命，机器大工业发展到自动化阶段。智能化工厂创造出了较高的生产效率，显露出巨大的竞争力，企业在“机器换人”中取得了一定的经济效益。这意味着率先使用机器人的个别企业 (A) 资本技术构成的提高 (B) 剩余价值来源的改变 (C) 所生产商品价值的提高 (D) 获得更多的社会平均利润",a:"(A)",sol:""},{n:"(42)",q:"【2012.4】2011年9月以来，美国爆发的“占领华尔街”抗议活动中，示威者打出“我们是99%”的标语，向极富阶层表示不满。漫画所显示的美国社会财富占有的两极分化，是资本主义制度下富人1% (A) 劳资冲突的集中体现 (B) 生产社会化的必然产物穷人99%研祝您 (C) 资本积累的必然结果 (D) 虚拟资本泡沫化的恶果不平衡的跷跷板",a:"(C)",sol:""},{n:"(43)",q:"【2018.19】为了追逐最大化的利润，资本家总是想方设法地进行资本积累，而资本积累的源泉是剩余价值。一般而言，资本积累规模的大小取决于 (A) 资本家对工人的剥削程度 (B) 劳动生产率的高低 (C) 资本家垫付资本的大小 (D) 所用资本与所费资本之间的差额",a:"(ABCD)",sol:"【简析】资本积累规模的大小取决于资本家对工人的剥削程度、劳动生产率的高低、所用资本和所费资本之间的差额以及资本家预付资本的大小。A、B、C、D均正确。"},{n:"(44)",q:"【2022.21】马克思、恩格斯在《共产党宣言》中指出：“资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。自然力的征服，机器的采用，化学在工业和农业中的应用，轮船的行驶，铁路的通行，电报的使用，整个整个大陆的开垦，河川的通航，仿佛用法术从地下呼唤出来的大量人口一过去哪一个世纪料想到在社会劳动里蕴藏有这样的生产力呢？”资本主义社会生产力迅速发展的主要原因是 (A) 资本追逐剩余价值的内在动力 (B) 市场激烈竞争的外在压力 (C) 无产阶级反对资产阶级的斗争 (D) 资本主义国家对市场的全面控制",a:"(AB)",sol:""},{n:"(45)",q:"【2001.文41某纺织厂因棉花价格上涨而增加了资本的垫支，它影响该厂的 (A) 资本技术构成 (B) 资本价值构成微信公众号：djky66 (C) 资本物质构成 (D) 资本有机构成（顶尖考研祝您上岸）",a:"(B)",sol:""},{n:"(46)",q:"【2009.7】某钢铁厂因铁矿石价格上涨，增加了该厂的预付资本数量，这使得该厂的资本构成产生了变化，所变化的资本构成是 (A) 资本技术构成 (B) 资本价值构成 (C) 资本物质构成 (D) 资本有机构成",a:"(B)",sol:""},{n:"(47)",q:"【2021.20】某服装厂为了实现更高的盈利，将原本依靠人工进行生产的流水线改造成了完全依靠机器进行生产的流水线。与此同时，由于受经济危机的影响，该服装厂从市场上采购的布料等生产原料价格也出现了大幅度的下降。在这种情况下，该服装厂资本构成会发生变化的是 (A) 资本有机构成 (B) 资本积累构成 (C) 资本技术构成 (D) 资本价值构成",a:"(ACD)",sol:""},{n:"(49)",q:"【2015.20】马克思指出：“资本主义积累不断地并且同它的能力和规模成比例地生产出相对的，即超过资本增殖的平均需要的，因而是过剩的或追加的工人人口。”“过剩的工人人口是积累或资本主义基础上的财富发展的必然产物，但是这种过剩人口反过来又成为资本主义积累的杠杆，甚至成为资本主义生产方式存在的一个条件。”上述论断表明( (A) 资本主义积累必然导致工人人口的供给相对于资本的需要而过剩 (B) 资本主义社会过剩人口之所以是相对的，是因为它不为资本价值增殖所需要 (C) 资本主义生产周期性特征需要有相对过剩的人口规律与之相适应 (D) 资本主义积累使得资本主义社会的人口失业规模呈现越来越大的趋势",a:"(ABC)",sol:""},{n:"(50)",q:"【2017.20】当今世界正处在新科技革命和产业革命的交汇点，以机器人技术为代表的科技产业发展十分迅速。机器人在生产过程中的广泛使用，使资本有机构成不断提高。然而，就一般意义而言，资本有机构成的提高实际上是 (A) 一个社会增长财富和消除贫困的根本途径 (B) 不以人的意志为转移的一般趋势 (C) 社会产生相对过剩人口的一个重要原因 (D) 由资本的本性决定的",a:"(BCD)",sol:""},{n:"(51)",q:"【1999.理6】产业资本划分为货币资本、生产资本、商品资本的依据是资本各个部分 (A) 在价值增殖过程中的作用不同 (B) 价值周转方式的不同 (C) 存在的物质形态不同 (D) 在循环中的职能不同",a:"(D)",sol:"【简析】依据产业资本在资本循环过程中的不同阶段所担负的职能的不同，划分为货币资本、生产资本和商品资本。D正确。"},{n:"(54)",q:"【2020.20】资本循环是资本实现价值增殖的重要前提。所谓资本循环，是指资本石嘉老师提示从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。产业资本固定资本、流动资本的划分和不变资本、循环过程中在空间上同时存在的资本形式有可变资本的划分的区别。 (A) 生产资本 (B) 借贷资本其一，划分的依据不同。固定资本、流动 (C) 货币资本 (D) 商品资本资本是根据生产资本之不同部分的价值的不同的转移方式划分的；不变资本、可变",a:"(ACD)",sol:""},{n:"(55)",q:"【1998.文21把生产资本区分为固定资本与流动资本，其依据是 (A) 在生产过程中不同的价值转移方式 (B) 在生产过程中不同的物质存在形态 (C) 不同部分在剩余价值生产过程的不同作用 (D) 不同部分的不同运动速度固定资本是指购买机器、厂房、设备等劳动资料的那一部分生产资本。它是不变资本的一部分。从实物形态上看，固定资本始终保持其物质形式，并在生产过程中多次发挥作用；从价值形态上看，固定资本一次投入，但在生产过程中却根据磨损程度分次转移到新产品中去。随着产品的不断售出，价值分次地转回到产业资本家手中。流动资本是指购买原料、燃料、辅助材料等劳动对象和购买劳动力的那一部分生产资本。它包括不变资本中的属于非固定资本的生产资本和全部可变资本。劳动对象的价值一次转移到新产品中去，并随着产品的售出一次收回。劳动力的价值虽然不能转移到新产品中去，但可以在生产过程中由劳动者把它重新创造出来。随着产品的售出，这部分价值也一次收回。表5-1生产资本的不同划分按生产资本在剩余价值生产资本各个部分按生产资本价值的周转方式的生产中的作用划分的实物形式特点划分djkv66微信公厂房建筑、机器设固定资本备等劳动资料老汇您上岸）不变资本原料、燃料、辅助材料等劳动对象流动资本可变资本劳动力",a:"(A)",sol:""},{n:"(60)",q:"【2001.文5】考察社会总资本再生产的核心问题是 (A) 价值如何增殖 (B) 价值和剩余价值的形成 (C) 剩余价值的实现 (D) 社会总产品的实现",a:"(D)",sol:""},{n:"(61)",q:"【2014.3】社会生产是连续不断进行的，这种连续不断重复的生产就是再生产。每次经济危机发生期间，总有许多企业或因产品积压、或因订单缺乏等致使其无法继续进行再生产而被迫倒闭。那些因产品积压而倒闭的企业主要是由于无法实现其生产过程中的 (A) 实物补偿 (B) 价值补偿 (C) 增殖补偿 (D) 劳动补偿1272024考研政治知识精讲讲义（马原分册）",a:"(B)",sol:""},{n:"(62)",q:"【2004.4】社会总资本扩大再生产的前提条件是 (A) I（v+m）=IIc (B) II（v+m）=Ic (C) I（v+m）>II (D) ⅡI（v+m）>Icdlikv66",a:"(C)",sol:""},{n:"(63)",q:"【1992.文12】资本主义工资之所以掩盖了剥削，是由于它 (A) 表现为劳动的价格 (B) 是劳动力的价值 (C) 是劳动者必要劳动创造的价值 (D) 是劳动力的价格或价值的转化形态",a:"(A)",sol:"【简析】工资表现为“劳动的价格”或工人全部劳动的报酬，这就模糊了工人必要劳动和剩余劳动的界限，掩盖了资本主义的剥削关系。A正确。"},{n:"(64)",q:"【2000.理6】在揭示资本主义工资的本质上，首先要区分 (A) 必要劳动和剩余劳动 (B) 劳动和劳动力 (C) 具体劳动和抽象劳动 (D) 私人劳动和社会劳动",a:"(B)",sol:""},{n:"(65)",q:"【2012.3】在资本主义社会里，资本家雇佣工人进行劳动并支付相应的工资。资本主义工资的本质是 (A) 工人所获得的资本家的预付资本 (B) 工人劳动力的价值或价格 (C) 工人所创造的剩余价值的一部分 (D) 工人全部劳动的报酬128·",a:"(B)",sol:"【简析】在资本主义制度下，工人的工资是劳动力的价值或价格，这是资本主义工资的本质。B正确。"},{n:"(67)",q:"【2000.文5】剩余价值转化为利润，是因为剩余价值被看作生产商品中（ (A) 所耗费的可变资本的增加额 (B) 所预付的不变资本的增加额 (C) 所预付的全部资本的增加额 (D) 所耗费的全部资本的增加额（二）利润转化为平均利润V66资本主义生产是为了获得利润，因此，不同部门之间如果利润率不同，资本家之间就会展开激烈的竞争，使资本从利润率低的部门转向利润率高的部门，从而导致利润率趋于平均化，不同部门的资本家按照等量资本获得等量利润的原则来瓜分剩余价值。按照平均利润来计算和获得的利润，叫作平均利润。随着利润转化为平均利润，商品价值就转化为生产价格。生产价格是商品价值的转化形式，是生产成本（c+v）与平均利润之和。生产成本是由生产中实际耗费的不变资本和可变资本构成的。在价值转化为生产价格的条件下，价值规律作用的形式发生了变化。商品不再以价值而是以生产价格为基础进行交换，市场价格的变动不再以价值为中心，而是以生产价格为中心。生产价格是价值的转化形式，商品按照生产价格而不是价值进行出售并不违背价值规律，而是价值规律实现形式发生了变化在利润平均化规律作用下，产业资本家获得产业利润，商业资本获得商业利润，银行资本家获得银行利润，农业资本家获得农业利润，这些不同部门的资本家瓜分到的利润只是平均利润。平均利润率规律的作用表明，平均利润率是剩余价值总量对社会总资本的比率，因此每个资本家所得利润多少不仅取决于他对本企业工人的剥削程度，而且还取决于整个资产阶级对整个工人阶级的剥削程度。资本家之间在瓜分剩余价值上固然有一定程度的利害冲突，但在加强对工人阶级的剥削以榨取更大量的剩余价值这一点上，却有着共同的阶级利益",a:"(C)",sol:""},{n:"(68)",q:"【2017.3】某企业投资汽车生产，生产一辆汽车所耗费的生产资料价值为15万元，支付给工人的工资为5万元，假定市场的平均利润率为10%，那么，在自由竞争条件下，该汽车的生产价格是 (A) 20万元 (B) 20.5万元 (C) 21.5万元 (D) 22万元1292024考研政治知识精讲讲义（马原分册）",a:"(D)",sol:""},{n:"(70)",q:"【2023.19】马克思的平均利润理论深刻阐明了资本主义社会利润转化为平均利润以及剩余价值被进一步分割的原理，在利润率平均化的过程中，仍然能获得平均利润的资本有 (A) 产业资本 (B) 农业资本 (C) 商业资本 (D) 借贷资本",a:"",sol:""},{n:"(71)",q:"【2011.20】19世纪中叶，马克思、恩格斯把社会主义由空想变为科学，奠定这一飞跃的理论基石是 (A) 阶级斗争学说 (B) 劳动价值论 (C) 唯物史观 (D) 剩余价值理论",a:"",sol:""},{n:"(72)",q:"【2009.21】“信用制度加速了生产力的物质上的发展和世界市场的形成；使这二者作为新生产形式的物质基础发展到一定的高度，是资本主义生产方式的历史使命。同时，信用加速了这种矛盾的暴力的爆发，即危机，因而加强了旧生产方式解体的各种因素。”马克思的这一论述表明，资本主义信用制度( (A) 已成为资本主义经济危机爆发的深层原因 (B) 促进了建立社会主义生产方式的物质基础的形成 (C) 加速了资本主义生产方式内部矛盾发展和解体要素的形成 (D) 既推动商品经济的发展，又加深了商品经济运行中的矛盾·131·2024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(73)",q:"【2011.19】2008年由美国次贷危机引发了全球性的经济危机，很多西方人感叹这危机的理论判断和精辟分析。马克思对资本主义经济危机科学分析的深刻性主要表现为 (A) 指明经济危机的实质是生产相对过剩 (B) 揭示造成相对过剩的制度原因是生产资料的资本主义私有制 (C) 指出经济危机的深层根源是人性的贪婪 (D) 强调政府对经济的干预是摆脱经济危机的根本出路",a:"",sol:""},{n:"(74)",q:"【2016.19】马克思说：“一切现实的危机的最终原因始终是：群众贫穷和群众的消费受到限制，而与此相对立，资本主义生产却竭力发展生产力，好像只有社会的绝对的消费能力才是生产力发展的界限。”这段论述表明 (A) 社会的绝对的消费能力导致了经济危机的发生 (B) 经济危机的发生根本上在于资本主义的基本矛盾 (C) 资本积累与无限扩大生产也是经济危机发生的原因 (D) 经济危机的发生与群众的贫穷及其消费能力受到限制有关",a:"",sol:""},{n:"(75)",q:"【2010.19】有一则寓言讲道：狐狸把鱼汤盛在平底的盘子里，请仙鹤来与它一起“平等”地喝鱼汤，结果仙鹤一点也没喝到，全被狐狸喝了。这则寓言给人们的启示是，尽管资产阶级宣布“法律面前人人平等”，但是( (A) 法律名义上的平等掩盖着事实上的不平等 (B) 这种形式上的平等即是资本主义制度的本质 (C) 它的实质是将劳资之间经济利益的不平等合法化 (D) 这种平等的权利是建立在财产不平等基础之上的权利",a:"",sol:""}],
  "mayuan_s22": [{n:"(1)",q:"【2011.18】在资本主义社会里，银行垄断资本和工业垄断资本密切地融合在一起，产生了一种新型的垄断资本，即金融资本。在金融资本形成的基础上，产生了金融寡头。金融寡头操纵、控制社会的主要方式有 (A) 通过“参与制”实现其在经济领域中的统治 (B) 通过同政府的“个人联合”实现其对国家机器的控制 (C) 通过政策咨询机构影响和左右内外政策 (D) 通过新闻媒体实现国民思想意识的一元化",a:"(ABC)",sol:""},{n:"(4)",q:"【2023.4】垄断组织依靠制定垄断制度获取垄断利润。在市场交易过程中，垄断利润高低受多重因素影响。为了避免遭受净亏损，垄断组织所能接受的最低价格是 (A) 成本价格 (B) 生产价格 (C) 垄断低价 (D) 垄断高价V66",a:"(B)",sol:""},{n:"(5)",q:"【2000.文6；理7】国家垄断资本主义的产生和发展，从根本上说是 (A) 国内市场竞争的结果 (B) 国际竞争激化的结果 (C) 垄断统治加强的结果 (D) 生产社会化和资本主义私人占有制之间矛盾发展的结果国家垄断资本主义的主要形式有五种：一是国家所有并直接经营的企业；二是国家与私人共有、合营企业；三是国家通过多种形式参与私人垄断资本的再生产过程，包括国家向私人垄断企业订货、提供补贴等；四是宏观调节，主要是国家运用财政政策、货币政策等经济手段，对社会总供求进行调节，以实现经济快速增长、充分就业、物价稳定和国际收支平衡的基本目标；五是微观规制，主要是国家运用法律手段规范市场秩序，限制垄断，保护竞争，维护社会公众的合法权益。微观规制主要有三种类型：其一是反托拉斯法；其二是公共事业规制；其三是社会经济规制138",a:"(D)",sol:"【简析】国家垄断资本主义的主要形式有：国家所有并直接经营企业；国家与私人共有、合营企业；国家通过多种形式参与私人垄断资本的再生产过程；宏观调节和微观规制。A、B、C、D均正确。"},{n:"(6)",q:"【2015.21】国家垄断资本主义是国家政权和私人垄断资本融合在一起的垄断资本主义。第二次世界大战结束以来，在国家垄断资本主义获得充分发展的同时，资本主义国家通过宏观调节和微观规制对生产、流通、分配和消费各个环节的干预也更加深人。其中，微观规制的类型主要有( (A) 公众生活规制 (B) 公共事业规制 (C) 社会经济规制 (D) 反托拉斯法国家垄断资本主义是垄断资本主义的新发展，它对资本主义经济的发展产生了积极的作用。首先，国家垄断资本主义的出现在一定程度上有利于社会生产力的发展。国家兴办了私人资本无力兴办的、适应新科技发展要求的巨大新型工业企业。其次，国家垄断资本主义在一定范围内突破了私人垄断资本的狭隘界限，适应了社会化大生产的要求，有利于缓解资本主义生产的无政府状态。再次，通过国家的收人再分配手段，使劳动人民生活水平有所改善和提高。最后，在国家垄断资本主义的参与和干预石磊老师提示下，各主要资本主义国家的产业升级和优化，加快了这些国家的现代化进程。国家垄断资本主义的出现并没有改变垄但是，国家垄断资本主义的出现并没有改变垄断资本主义的性质。国家垄断资本断资本主义的性质，并没有从根本上消主义的出现是资本主义经济制度内的经济关系调整，并没有从根本上消除资本主义的除资本主义的基本矛盾。其实质是为了基本矛盾。国家垄断资本主义有各种不同的形式，但其实质都是私人垄断资本利用国维护垄断资产阶级的整体利益和长远利益，而和国家政权相结合的一种垄断资家机器来为其服务的手段，是私人垄断资本为了维护垄断统治和获取高额垄断利润，本主义形式。为了维护垄断资产阶级的整体利益和长远利益，而和国家政权相结合的一种垄断资本主义形式。众号：diky66",a:"(BCD)",sol:""},{n:"(7)",q:"【2009.6】在国家垄断资本主义条件下，政府对经济生活进行干预和调节的实质是 (A) 维护垄断资产阶级的整体利益和长远利益 (B) 维持资本主义经济稳定增长 (C) 消除或防止经济危机的爆发 (D) 提高资本主义社会的整体福利水平",a:"(A)",sol:""},{n:"(8)",q:"【2016.4】20世纪70年代以来，西方资本主义国家的金融资本急剧膨胀，这一方经济过度虚拟化，导致金融危机频繁发面促进了资本主义的发展，另一方面也造成了经济过度虚拟化，致使金融危机频生，不仅给资本主义经济，也给全球经繁发生。西方资本主义金融资本快速发展壮大的重要制度条件是济带来灾难。 (A) 金融自由化与金融创新 (B) 技术创新与大力发展互联网金融 (C) 全面私有化与放松金融监管 (D) 去工业化与大力发展现代服务业",a:"(A)",sol:""},{n:"(9)",q:"【2023.20】自20世纪70年代由美国主导的布雷顿森林体系崩溃以来，资本主义国家的金融垄断资本获得了快速发展。金融垄断资本得以形成和壮大的重要制度条件是（公众号66 (A) 金融创新 (B) 金融市场管理加强 (C) 金融自由化 (D) 金融危机频繁发生",a:"(AC)",sol:""},{n:"(10)",q:"【1998.理5】当代资本主义国际垄断组织的主要形式是 (A) 国际卡特尔 (B) 混合联合企业 (C) 跨国公司 (D) 国际康采恩",a:"(C)",sol:"【简析】国家垄断资本主义的主要形式有：国家所有并直接经营企业；国家与私人共有、合营企业；国家通过多种形式参与私人垄断资本的再生产过程；宏观调节和微观规制。A、B、C、D均正确。"},{n:"(11)",q:"【2006.22】垄断资本主义的基本经济特征包括 (A) 垄断组织在经济生活中起决定作用 (B) 资本输出有了特别重要的意义 (C) 在金融资本的基础上形成金融寡头的统治 (D) 垄断使竞争趋于缓和141·2024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(12)",q:"【2016.20】20世纪80年代以来，随着冷战的结束，分割的世界经济体系也随之被打破，技术、资本、商品等真正实现了全球范围的流动，各国之间的经济联系日益密切，相互合作、相互依存大大加强，世界进入经济全球化迅猛发展的新时代。促使经济全球化迅猛发展的因素有 (A) 科学技术的进步和生产力的快速发展 (B) 出现了适宜于全球化的企业组织形式 (C) 企业不断进行的技术创新与管理创新 (D) 各国经济体制变革供给出的有利制度条件",a:"",sol:""},{n:"(13)",q:"【2020.21】为了加强对各国垄断资本的协调和制约，第二次世界大战后，国际垄断资本建立了国际货币基金组织、世界银行和世界贸易组织等国际经济机构。这些国际经济机构在协调和合作的基础上促进了经济全球化的发展，主要表现在( (A) 加强了各国和各经济体之间的联系 (B) 推动了商品和服务贸易的迅速增加 (C) 有效应对全球性经济波动和经济危机 (D) 加快了资本和技术等要素的国际流动·1432024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(14)",q:"【2017.4】从历史发展的角度看，资本主义生产资料所有制是不断演进和变化的。当今资本主义社会，居主导地位的资本所有制形式是 (A) 私人资本所有制 (B) 法人资本所有制 (C) 私人股份资本所有制 (D) 垄断资本私人所有制（二）劳资关系和分配关系的变化随着科学技术的进步和社会生产力的发展，特别是随着工人阶级反抗力量的不断壮大，资本家及其代理人开始采取一些缓和劳资关系的激励制度，促使工人自觉地服从资本家的意志。这些制度主要有：其一，职工参与决策。这一制度旨在协调劳资关系，缓和阶级矛盾。按照这种制度，有的国家在企业的监事会中，劳资双方各占一半席位，对企业重大问题共同进行决策。其二，终身雇佣。这是一种用工制度。即工人一旦进人公司工作，只要不违反公司纪律，就会终身被雇佣。目的在于增强工人对企业的归属意识，从而更加自觉地服从资本家的统治。其三，职工持股。该制度旨在通过使职工持有一部分本公司的股份来调动工人的生产积极性，使工人产生归属感，在生产中努力提高劳动生产率，增加剩余价值生产。144",a:"",sol:""},{n:"(15)",q:"【2013.20】伴随着生产力发展、科技进步及阶级关系调整，当代资本主义社会的劳资关系和分配关系发生了很大变化。其中资本家及其代理人为缓和劳资关系所采取的激励制度有( (A) 职工参与决策制度 (B) 职工终身雇佣制度 (C) 职工选举管理者制度 (D) 职工持股制度（三）社会阶层、阶级结构的变化社会阶层、阶级结构的变化主要表现在：一是传统的资本家的地位和作用已经发生了很大变化。大公司内部资本所有权与控制权发生分离，拥有所有权的资本家一般不再直接经营和管理企业，而是靠手中拥有和掌握的企业股票等有价证券的利息收入为生。二是高级职业经理成为大公司经营活动的实际控制者。大公司的高级管理人员在企业中控制企业决策，组织和指挥生产，控制人事调动，处理劳资纠纷，因而具有控制企业的实际权力。三是知识型和服务型劳动者的数量不断增加，劳动方式发生了新变化。随着科学技术革命的不断深人，工人阶级的受教育水平和科技文化素质显著提高。从事体力劳动的蓝领工人越来越少，而从事脑力劳动的白领工人不断增加，越来越多的工人在生产过程中从事监督者、调节者和操作者的工作，实现了从传统劳动方式向现代劳动方式的转变。",a:"",sol:""},{n:"(16)",q:"【2018.20】与第二次世界大战之前的资本主义相比，当代资本主义生产关系中的社会阶层、阶级结构发生了许多新的变化，主要表现在 (A) 高级职业经理成为资本主义社会大公司经营活动的实际控制者 (B) 资本家由从前的直接生产经营者变成了以剪息票为生的食利者 (C) 职工持股和参与决策使得劳动者成为资本家集团的重要力量 (D) 知识型和服务型劳动者数量随科技革命不断深人而持续地增加",a:"",sol:""},{n:"(17)",q:"【2022.4】与第二次世界大战前的资本主义相比，当代资本主义在许多方面已经并正在发生着深刻的变化。当代资本主义社会，大公司经营活动的实际控制者是 (A) 高级职业经理 (B) 股东大会 (C) 监事会 (D) 董事长（四）经济调节机制和经济危机形态的变化在经济调节机制变化的同时，经济危机形态也发生了变化，表现在：危机对社会经济运行的干扰减轻，破坏性减弱，生产下降的幅度减小，失业率有所降低，企业破产的数量减少；危机周期的长度缩短；经济危机的四个阶段（即危机阶段、萧条阶段、复苏阶段和高涨阶段）之间的差别有所减弱，各阶段的交替过程已不如过去那样明显；金融危机对整个经济危机的影响加强。",a:"",sol:""},{n:"(18)",q:"【2014.20】第二次世界大战结束以来，随着国家垄断资本主义的形成和发展，资产阶级国家对经济进行的干预明显加强，从而使得资本主义社会的经济调节机制发生了显著变化。与这种变化相适应，经济危机形态也发生了很大变化，其主要表现是 (A) 经济危机通常由国家间的贸易失衡直接引发 (B) 经济危机各阶段的交替过程已不十分明显 (C) 经济危机更多地表现为金融危机的频繁发生 (D) 经济危机的破坏作用只局限于发达资本主义国家1452024考研政治知识精讲讲义（马原分册）",a:"",sol:""},{n:"(19)",q:"【2014.4】与第二次世界大战前的资本主义相比，当代资本主义在许多方面已经并正在发生着深刻的变化，正确分析这些新变化发生的原因，有利于我们科学而全面地认识当代资本主义社会。导致当代资本主义新变化发生的根本推动力量是 (A) 工人阶级争取自身权利的斗争祝您上岸） (B) 科学技术革命和生产力的发展 (C) 改良主义政党对资本主义制度的改革 (D) 社会主义制度的优越性对资本主义的影响（二）当代资本主义新变化的实质首先，当代资本主义发生的变化从根本上说是人类社会发展一般规律和资本主义经济规律作用的结果。为适应科学技术进步和生产社会化的发展，必然要求调整和变革旧的生产关系，新的适应生产社会化要求的生产关系必然将不断出现和发展。其次，当代资本主义发生的变化是在资本主义制度基本框架内的变化，并不意味着资本主义生产关系的根本性质发生了变化。从当代资本主义发展的实际情况来看，生产资料私有制仍然是资本主义的基本经济制度，资本追逐剩余价值的本性并没有改变，改变的只是获取剩余价值的方式和方法。社会福利制度缓和了资本主义分配关系食石磊老师提示的矛盾，但并没有改变导致财富占有两极分化的制度基础。资本主义国家政府虽然重当代资本主义的新变化并没有改变资本主义制度的本质，并没有克服资本主义的基视对经济的协调，但仍然难以防止和克服金融危机和经济危机本矛盾，也没有改变马克思主义关于资本这一切表明，当代资本主义的新变化并没有改变资本主义制度的本质，并没有克主义的基本论断的科学性。服资本主义的基本矛盾，也没有改变马克思主义关于资本主义的基本论断的科学性",a:"",sol:""},{n:"(20)",q:"【2021.4】马克思指出，资本主义生产在“发展社会劳动的生产力”的同时，也“不自觉地创造着一种更高级的生产形式的物质条件”。这表明 (A) 资本越扩张越不利于创造更多的物质财富 (B) 资本主义生产方式能够无限制地解放和发展社会生产力 (C) 资本越发展越有利于巩固资本主义 (D) 资本主义生产是一种历史的、过渡性的生产方式148·",a:"(D)",sol:""},{n:"(21)",q:"【2012.20】关于共产主义理想实现的必然性，马克思主义除了从社会形态更替规律上作了一般性的历史观论证外，还通过对资本主义社会的深人实证的剖析，科学地论证了 (A) 资本主义的历史暂时性 (B) 资本主义发展的自我否定的趋势djky66 (C) 资本主义灭亡的具体途径和方式 (D) 工人阶级推翻旧世界建设新世界的历史使命",a:"(ABD)",sol:""},{n:"(22)",q:"【2019.20】资本主义必然为社会主义所代替，并不意味着资本主义将在短期内自行消亡。资本主义向社会主义的过渡必然是一个复杂的、长期的历史过程，其原因在于 (A) 任何社会形态的存在都有绝对稳定性 (B) 资本主义的发展具有不平衡性 (C) 资本主义社会具有一定的自我调节能力 (D) 当代资本主义的发展还显示出生产关系对生产力容纳的空间1492024考研政治知识精讲讲义（马原分册）",a:"(BCD)",sol:""}],
  "mayuan_s26": [{n:"(1)",q:"【2016.21】1516年，英国人托马斯·莫尔发表了《乌托邦》一书，标志着空想社会主义的诞生。1848年，马克思、恩格斯发表了《共产党宣言》，标志着科学社会主义的产生，社会主义实现了从空想到科学的历史性飞跃。科学社会主义超越空想社会主义之处在于 (A) 对资本主义进行了无情的批判 (B) 对未来社会进行了细致的描绘 (C) 揭示了资本主义必然灭亡的经济根源 (D) 找到了实现理想社会的现实道路",a:"(CD)",sol:""},{n:"(3)",q:"【2015.4】马克思主义政党是科学社会主义与工人运动相结合的产物，是工人阶级的先锋队。这表明 (A) 马克思主义政党即工人阶级本身 (B) 马克思主义政党以工人阶级为基础 (C) 马克思主义政党的阶级性是其先进性的根本前提 (D) 马克思主义政党的先进性决定了工人阶级的先进性1512024考研政治知识精讲讲义（马原分册）",a:"(B)",sol:""},{n:"(4)",q:"【2021.21】1871年爆发的巴黎公社革命，是无产阶级夺取政权的第一次伟大尝试。马克思、恩格斯深刻总结了巴黎公社的经验，高度评价了巴黎公社的意义。马克思、恩格斯总结的巴黎公社的经验主要有( (A) 无产阶级政权是为人民服务的机关 (B) 必须打碎旧的国家机器，建立无产阶级的新型国家 (C) 无产阶级革命取得成功并保持胜利果实的首要条件是要有革命的武装 (D) 必须建立无产阶级政党，发挥党的政治领导作用",a:"(ABCD)",sol:"【简析】巴黎公社采取的两项重要措施：一是规定所有公职人员无论职位高低，实行全面的选举制和撤换制；二是取消高薪制，规定任何工作人员年薪不得超过熟练工人的工资水平。C、D正确，A、B错误。"},{n:"(6)",q:"【2020.4】十月革命之前，列宁总结当时变化了的新情况，得出“社会主义可能首先在少数甚至在单独一个资本主义国家内获得胜利”的结论。列宁得出这个结论的理论依据是( (A) 资本主义经济和政治发展不平衡规律 (B) 资本主义国家的不断衰落 (C) 科学社会主义理论的广泛传播 (D) 无产阶级力量的不断壮大152·",a:"(A)",sol:""},{n:"(7)",q:"【2011.4】邓小平指出：“社会主义究竞是个什么样子，苏联搞了很多年，也并没有完全搞清楚。可能列宁的思路比较好，搞了个新经济政策，但是后来苏联的模式僵化了。”列宁的新经济政策关于社会主义的思路之所以“比较好”，是因为djky66 (A) 提出了比较系统的社会主义建设的纲领 (B) 根据俄国的实际情况来探索社会主义建设的道路 (C) 为俄国找到了一种比较成熟的社会主义发展模式上岸） (D) 按照马克思、恩格斯关于未来的设想来建设社会主义",a:"(B)",sol:""},{n:"(8)",q:"【2014.21】1926一1927年年初，邓小平在莫斯科中山大学留学一年。此时正值列宁的新经济政策在莫斯科和整个苏联燎原般发展，国家经济全面开花，市场上商品丰富、品类繁多，商店、饭馆、咖啡馆随处可见。邓小平到中山大学第一天就收到了一大堆日用品，一日三餐也非常丰富。在此期间，邓小平还认真阅读和摘抄了苏联领导人关于新经济政策的许多论述。这一段经历对邓小平后来思考建设“有中国特色的社会主义”具有一定的启示。邓小平与列宁在如何建设社会主义的探索中有许多相通之处，主要有 (A) 学习和利用资本主义的文明成果 (B) 把大力发展生产力、提高劳动生产率放在首要地位 (C) 在多种经济成分并存的条件下，利用商品、货币和市场发展经济 (D) 优先发展重工业，快速实现从农业国到工业国的转变",a:"(ABC)",sol:""},{n:"(9)",q:"【2017.21】1921年3月，俄共（布）召开十大，决定从战时共产主义政策过渡到新经济政策。在实施新经济政策期间，列宁对苏维埃俄国如何建设社会主义进行了深刻的理论思考，提出了许多精辟的论述，其主要内容包括( (A) 允许多种经济成分并存，可以利用商品、货币和市场发展经济 (B) 把大力发展生产力、提高劳动生产率放在首要地位 (C) 把建设社会主义作为一个长期探索、不断实践的过程 (D) 可以利用资本主义来建设社会主义1532024考研政治知识精讲讲义（马原分册）",a:"(ABCD)",sol:"【简析】列宁的论述主要包括：把建设社会主义作为一个长期探索、不断实践的过程；把大力发展生产力、提高劳动生产率放在首要地位；在多种经济成分并存的条件下，利用商品、货币和市场发展经济；利用资本主义建设社会主义。A、B、C、D均正确。"},{n:"(10)",q:"【2023.21】十月革命胜利后，为捍卫年轻的苏维埃政权，列宁领导的苏维埃政权从1918年夏到1921年春实行了战时共产主义政策。战时共产主义政策是苏维埃俄国面临帝国主义武装干涉和国内战争被迫采取的一种临时性政策。战时共产主义政策的主要内容包括( (A) 余粮收集制 (B) 取消商品货币关系 (C) 发展多种所有制 (D) 支持农民耕种自留地",a:"(AB)",sol:"【简析】战时共产主义政策以余粮收集制和取消商品货币关系为主要特征。A、C正确。B、D是新经济政策时期实行的政策，不符合题意。"},{n:"(11)",q:"【2019.21】习近平指出：“当代中国的伟大社会变革，不是简单延续我国历史文化的母版，不是简单套用马克思主义经典作家设想的模板，不是其他国家社会主义实践的再现，不是国外现代化发展的翻版。”这对我们理解科学社会主义基本原则的启示是 (A) 科学社会主义绝不是一成不变的教条 (B) 科学社会主义与资本主义生产方式没有必然的联系 (C) 科学社会主义是人类优秀文化传统的历史延续 (D) 科学社会主义在不同的时代具有不同的内容和形式",a:"(ACD)",sol:""},{n:"(12)",q:"【1998.理6】列宁说：“如果社会主义在经济上尚未成熟，任何起义也创造不出社会主义来。”这就是说 (A) 社会主义革命只能在经济发达的国家发生和取得胜利 (B) 社会主义革命需要一定的物质前提 (C) 只能靠经济力量去实现社会主义 (D) 社会主义革命能够在资本主义内部自发产生156",a:"(B)",sol:""},{n:"(15)",q:"【2013.21】自第一个社会主义国家建立以来，社会主义事业的发展并不是一帆风顺的。社会主义发展道路的多样性以及发展过程中的前进性和曲折性的实践告诉我们 (A) 坚持社会主义，不等于要坚持某种单一的社会主义模式 (B) 发展社会主义，不等于不认可西方资本主义的文明成果 (C) 改革或抛弃某种社会主义模式，不等于改掉或抛弃社会主义 (D) 某种社会主义模式的失败，不等于整个社会主义事业的失败微信公众号：djky66（顶尖考研祝您上岸）158",a:"(ABCD)",sol:""}],
  "mayuan_s30": [{n:"(2)",q:"【2007.31马克思根据人的发展状况把人类历史划分为三大形态。它们是（ (A) 自然经济社会、商品经济社会、产品经济社会 (B) 原始公有制社会、私有制社会、共产主义公有制社会 (C) 农业社会、工业社会、信息社会 (D) 人的依赖性社会、物的依赖性社会、人的自由全面发展社会3.12010.111894年1月3日，意大利人卡内帕给恩格斯写信，请求他为即将在日内瓦出版的《新纪元》周刊的创刊号题词，而且要求尽量用简短的字句来表述未来的社会主义纪元的基本思想，以区别于伟大诗人但丁对旧纪元所作的“一些人统治，另一些人受苦难”的界定。恩格斯回答说，这就是：“代替那存在着阶级和阶级对立的资产阶级旧社会的，将是这样一个联合体，在那里，每个人的自由发展是一切人的自由发展的条件。”这段话表明，马克思主义追求的根本价值目标是",a:"(D)",sol:""},{n:"(4)",q:"【2013.17】马克思主义是关于无产阶级和人类解放的科学，实现共产主义是全人类解放的根本体现。人类解放包括 (A) 从自然的压迫下解放出来 (B) 从客观规律的制约下解放出来 (C) 从旧的社会关系的束缚下解放出来 (D) 从旧的传统观念的禁下解放出来",a:"(ACD)",sol:""}],
};
